def sendemail(recipients, subject, header=None, message=None, content=None, reference_name=None, reference_doctype=None, sender=None, cc=None, attachments=None, delayed=False, args=None, template=None, is_external_mail=False, is_scheduler_email=False):
    logo = 'https://one-fm.com/files/ONEFM_Identity.png'
    template = 'default_email'
    actions = pdf_link = workflow_state = ''
    doc_link = '#'
    mandatory_field = None
    field_labels = None
    head = header[0] if header else ''
    if not message:
        message = ' '
    if is_scheduler_email:
        is_scheduler_emails_enabled = frappe.db.get_single_value('ONEFM General Setting', 'enable_scheduler_event_emails')
        if not is_scheduler_emails_enabled:
            return
    if 'Administrator' in recipients:
        if isinstance(recipients, list):
            recipients.remove('Administrator')
        else:
            recipients = recipients.replace('Administrator', '')
    if args:
        template = 'default_email_with_workflow'
        head = 'Workflow Action'
        actions = args.get('actions')
        message = args.get('message')
        pdf_link = args.get('pdf_link')
        doc_link = args.get('doc_link')
        workflow_state = args.get('workflow_state')
        mandatory_field = args.get('mandatory_field')
        field_labels = args.get('field_labels')
    if type(recipients) == str:
        recipients = [recipients]
    if not is_external_mail:
        recipients = [recipient for recipient in recipients if is_email_notifications_allowed(recipient)]
        if not sender:
            sender = 'Administrator'
    if recipients and len(recipients) > 0:
        frappe.sendmail(template=template, recipients=recipients, sender=sender, cc=cc, subject=subject, args=dict(header=head, subject=subject, message=message, content=content, reference_name=reference_name, reference_doctype=reference_doctype, logo=logo, actions=actions, pdf_link=pdf_link, doc_link=doc_link, workflow_state=workflow_state, mandatory_field=mandatory_field, field_labels=field_labels), attachments=attachments, delayed=delayed)

