def set_series_for(doc, doctype, ol):
    options = scrub_options_list(ol)
    prop_dict = {'options': '\n'.join(options)}
    for prop in prop_dict:
        ps_exists = frappe.db.get_value('Property Setter', {'field_name': 'naming_series', 'doc_type': doctype, 'property': prop})
        if ps_exists:
            ps = frappe.get_doc('Property Setter', ps_exists)
            ps.value = prop_dict[prop]
            ps.save()
        else:
            ps = frappe.get_doc({'doctype': 'Property Setter', 'doctype_or_field': 'DocField', 'doc_type': doctype, 'field_name': 'naming_series', 'property': prop, 'value': prop_dict[prop], 'property_type': 'Text', '__islocal': 1})
            ps.save()
    frappe.clear_cache(doctype=doctype)

def check_duplicate_naming_series(set_options):
    parent = list(set(frappe.db.sql_list("select dt.name\n            from `tabDocField` df, `tabDocType` dt\n            where dt.name = df.parent and df.fieldname='naming_series' and dt.name != 'Supplier'") + frappe.db.sql_list("select dt.name\n            from `tabCustom Field` df, `tabDocType` dt\n            where dt.name = df.dt and df.fieldname='naming_series' and dt.name != 'Supplier'")))
    sr = [[frappe.get_meta(p).get_field('naming_series').options, p] for p in parent]
    dt = frappe.get_doc('DocType', 'Supplier')
    options = scrub_options_list(set_options.split('\n'))
    for series in options:
        validate_series(dt, series)
        for i in sr:
            if i[0]:
                existing_series = [d.split('.')[0] for d in i[0].split('\n')]
                if series.split('.')[0] in existing_series:
                    frappe.throw(_('Series {0} already used in {1}').format(series, i[1]))

def scrub_options_list(ol):
    options = list(filter(lambda x: x, [cstr(n).strip() for n in ol]))
    return options

