def queue_send_workflow_action_email(doc, recipients):
    if recipients and type(recipients) != list:
        recipients = [recipients]
    workflow = get_workflow_name(doc.get('doctype'))
    next_possible_transitions = get_next_possible_transitions(workflow, get_doc_workflow_state(doc), doc)
    user_data_map = get_users_next_action_data(next_possible_transitions, doc, recipients)
    common_args = get_common_email_args(doc)
    common_args.pop('attachments')
    mandatory_field, labels = get_mandatory_fields(doc)
    message = common_args.pop('message', None)
    subject = f'Workflow Action on {_(doc.doctype)} - {_(doc.workflow_state)}'
    pdf_link = get_url_to_form(doc.get('doctype'), doc.name)
    if not list(user_data_map.values()):
        email_args = {'recipients': recipients, 'args': {'message': message, 'doc_link': frappe.utils.get_url(doc.get_url()), 'workflow_state': doc.workflow_state, 'mandatory_field': mandatory_field, 'field_labels': labels}, 'reference_name': doc.name, 'reference_doctype': doc.doctype}
        email_args.update(common_args)
        email_args['subject'] = subject
        frappe.enqueue(method=sendemail, queue='short', **email_args)
    else:
        for d in [i for i in list(user_data_map.values()) if i.get('email') in recipients]:
            email_args = {'recipients': recipients, 'args': {'actions': list(deduplicate_actions(d.get('possible_actions'))), 'message': message, 'pdf_link': pdf_link, 'doc_link': frappe.utils.get_url(doc.get_url()), 'workflow_state': doc.workflow_state, 'mandatory_field': mandatory_field, 'field_labels': labels}, 'reference_name': doc.name, 'reference_doctype': doc.doctype}
            email_args.update(common_args)
            email_args['subject'] = subject
        frappe.enqueue(method=sendemail, queue='short', **email_args)

