def query_db_list(query_list, commit=False):
    try:
        credentials = get_db_config()
        connection = pymysql.connect(host=credentials.host, user=credentials.user, password=credentials.passwd, database=credentials.user, cursorclass=pymysql.cursors.DictCursor)
        result = None
        with connection:
            connection.autocommit(True)
            with connection.cursor() as cursor:
                for i in query_list:
                    cursor.execute(i)
            if commit:
                connection.commit()
        return frappe._dict({'error': False, 'data': result})
    except Exception as e:
        return frappe._dict({'error': True, 'msg': str(e), 'data': result})

def get_holiday_today(curr_date):
    start_date = getdate(curr_date).replace(day=1, month=1)
    end_date = getdate(start_date).replace(day=31, month=12)
    holidays = frappe.db.sql(f"\n\t\tSELECT h.parent as holiday, h.holiday_date, h.description FROM `tabHoliday` h\n\t\tJOIN `tabHoliday List` hl ON hl.name=h.parent\n\t\tWHERE hl.from_date='{start_date}' AND hl.to_date='{end_date}' AND h.holiday_date= '{curr_date}' ", as_dict=1)
    holiday_dict = {}
    for i in holidays:
        if holiday_dict.get(i.holiday):
            holiday_dict[i.holiday] = {**holiday_dict[i.holiday], **{str(i.holiday_date): i.description}}
        else:
            holiday_dict[i.holiday] = {str(i.holiday_date): i.description}
    return holiday_dict

