@frappe.whitelist()
def get_current_shift(employee):
    try:
        nowtime = now_datetime()
        sql = f"""\n            SELECT sa.*,\n                DATE_SUB(sa.start_datetime, INTERVAL st.begin_check_in_before_shift_start_time MINUTE) as checkin_time,\n                DATE_ADD(sa.end_datetime, INTERVAL st.allow_check_out_after_shift_end_time MINUTE) as checkout_time,\n                sa.end_datetime as actual_end_time\n            FROM `tabShift Assignment` sa\n            JOIN `tabShift Type` st ON sa.shift_type = st.name\n            WHERE sa.employee="{employee}"\n            AND sa.status="Active"\n            AND sa.docstatus=1\n            AND '{nowtime}' >= DATE_SUB(sa.start_datetime, INTERVAL st.begin_check_in_before_shift_start_time MINUTE)\n            AND '{nowtime}' <= DATE_ADD(sa.end_datetime, INTERVAL st.allow_check_out_after_shift_end_time MINUTE)\n            ORDER BY sa.start_datetime ASC\n            """
        shifts = frappe.db.sql(sql, as_dict=1)
        if shifts:
            current_shift = None
            for shift in shifts:
                checkin = frappe.db.get_list('Employee Checkin', filters={'employee': employee, 'shift_assignment': shift.name}, fields=['log_type', 'time', 'shift_assignment'], order_by='time desc', limit=1)
                if checkin:
                    last_log = checkin[0]
                    if last_log.log_type == 'IN':
                        if shift.checkin_time <= nowtime <= shift.checkout_time:
                            current_shift = shift
                            break
                    elif last_log.log_type == 'OUT':
                        if shift.actual_end_time <= last_log.time <= shift.checkout_time:
                            continue
                        else:
                            current_shift = shift
                            break
                elif shift.checkin_time <= nowtime <= shift.checkout_time:
                    current_shift = shift
                    break
            if current_shift:
                data = frappe.get_doc('Shift Assignment', current_shift.name)
                if current_shift.checkin_time > nowtime:
                    minutes = int((current_shift.checkin_time - nowtime).total_seconds() / 60)
                    return {'type': 'Early', 'data': data, 'time': minutes}
                elif current_shift.checkout_time < nowtime:
                    minutes = int((nowtime - current_shift.checkout_time).total_seconds() / 60)
                    return {'type': 'Late', 'data': data, 'time': minutes}
                elif current_shift.checkin_time <= nowtime <= current_shift.checkout_time:
                    return {'type': 'On Time', 'data': data, 'time': 0}
            for shift in shifts:
                if shift.checkin_time > nowtime:
                    data = frappe.get_doc('Shift Assignment', shift.name)
                    minutes = int((shift.checkin_time - nowtime).total_seconds() / 60)
                    return {'type': 'Upcoming', 'data': data, 'time': minutes}
            return False
        return False
    except Exception as e:
        frappe.log_error(message=frappe.get_traceback(), title='Error while getting current shift')
        return False

@frappe.whitelist()
def check_existing():
    """API to determine the applicable Log type.
    The api checks employee's last lcheckin log type. and determine what next log type needs to be
    Returns:
        True: The log in was "IN", so his next Log Type should be "OUT".
        False: either no log type or last log type is "OUT", so his next Ltg Type should be "IN".
    """
    employee = frappe.get_value('Employee', {'user_id': frappe.session.user})
    if not employee:
        return response('Employee not found', 404, None, 'Employee not found')
    shift_exists = get_current_shift(employee)
    if not shift_exists:
        return response('Resource Not Found', 404, None, 'No Active Shift Found')
    if shift_exists['type'] == 'On Time':
        curr_shift = shift_exists['data']
    if not curr_shift:
        return response('Employee not found', 404, None, 'Employee not found')
    log_type = curr_shift.get_next_checkin_log_type()
    if log_type == 'IN':
        return response('success', 200, True, '')
    return response('success', 200, False, '')

