    if filters:
        conditions = []
        for k, v in iteritems(filters):
            if isinstance(v, list):
                for value in v:
                    conditions.append(str(k) + '=' + '["' + str(value[0] + '"' + ',' + '"' + str(value[1]) + '"]'))
