@if_lending_app_installed
def set_loan_repayment(doc: 'SalarySlip'):
    doc.total_loan_repayment = 0
    doc.total_interest_amount = 0
    doc.total_principal_amount = 0
    if not doc.get('loans', []):
        loan_details = _get_loan_details(doc)
        for loan in loan_details:
            amounts = calculate_hybrid_amounts(loan.name, doc.start_date, doc.end_date)
            if amounts['interest_amount'] or amounts['payable_principal_amount']:
                doc.append('loans', {'loan': loan.name, 'total_payment': amounts['interest_amount'] + amounts['payable_principal_amount'], 'interest_amount': amounts['interest_amount'], 'principal_amount': amounts['payable_principal_amount'], 'loan_account': loan.loan_account, 'interest_income_account': loan.interest_income_account})
    if not doc.get('loans'):
        doc.set('loans', [])
    else:
        doc.has_multiple_salary_structure = 1
    for payment in doc.get('loans', []):
        amounts = calculate_hybrid_amounts(payment.loan, doc.start_date, doc.end_date)
        total_amount = amounts['interest_amount'] + amounts['payable_principal_amount']
        if payment.total_payment > total_amount:
            frappe.throw(_('Row {0}: Paid amount {1} is greater than pending amount {2} against loan {3}').format(payment.idx, frappe.bold(payment.total_payment), frappe.bold(total_amount), frappe.bold(payment.loan)))
        doc.total_interest_amount += payment.interest_amount
        doc.total_principal_amount += payment.principal_amount
        doc.total_loan_repayment += payment.total_payment

def calculate_hybrid_amounts(loan_name, start_date, end_date):
    accrued_entries = frappe.db.sql('
        SELECT SUM(interest_amount - paid_interest_amount) as interest_amount,
               SUM(payable_principal_amount - paid_principal_amount) as principal_amount
        FROM `tabLoan Interest Accrual`
        WHERE loan = %s 
        AND due_date >= %s 
        AND due_date <= %s
        AND docstatus = 1
        AND (interest_amount - paid_interest_amount > 0 OR payable_principal_amount - paid_principal_amount > 0)
    ', (loan_name, start_date, end_date), as_dict=True)
    if accrued_entries and accrued_entries[0] and (accrued_entries[0].interest_amount or accrued_entries[0].principal_amount):
        return {'interest_amount': flt(accrued_entries[0].interest_amount or 0), 'payable_principal_amount': flt(accrued_entries[0].principal_amount or 0)}
    else:
        return calculate_schedule_based_amounts(loan_name, start_date, end_date)

def calculate_schedule_based_amounts(loan_name, start_date, end_date):
    amounts = {'interest_amount': 0.0, 'payable_principal_amount': 0.0}
    schedule_doc = frappe.db.get_value('Loan Repayment Schedule', {'loan': loan_name}, 'name')
    if not schedule_doc:
        return amounts
    due_schedules = frappe.db.sql('\n        SELECT \n            principal_amount, \n            interest_amount,\n            total_payment,\n            IFNULL(custom_amount_paid_via_additional_payment, 0) as additional_payment\n        FROM `tabRepayment Schedule`\n        WHERE parent = %s \n        AND payment_date >= %s\n        AND payment_date <= %s\n        AND total_payment > 0\n        ORDER BY idx ASC\n    ', (schedule_doc, start_date, end_date), as_dict=True)
    for schedule in due_schedules:
        remaining_total = flt(schedule.total_payment) - flt(schedule.additional_payment)
        if remaining_total > 0:
            original_total = flt(schedule.total_payment)
            ratio = remaining_total / original_total if original_total > 0 else 0
            remaining_principal = flt(schedule.principal_amount) * ratio
            remaining_interest = flt(schedule.interest_amount) * ratio
            amounts['payable_principal_amount'] += remaining_principal
            amounts['interest_amount'] += remaining_interest
    return amounts

@frappe.whitelist()
def get_ot_days(employee, start_date, end_date):
    ot_schedule = frappe.get_all('Employee Schedule', filters={'date': ['between', [start_date, end_date]], 'employee': employee, 'roster_type': 'Over-Time'}, fields=['COUNT(*) as working_ot_days'])[0].working_ot_days
    return ot_schedule

def get_unmarked_days_based_on_doj_or_relieving(self, unmarked_days, include_holidays_in_total_working_days, start_date, end_date=None):
    """
	Exclude days before DOJ or after
	Relieving Date from unmarked days
	"""
    from erpnext.setup.doctype.employee.employee import is_holiday
    if include_holidays_in_total_working_days:
        unmarked_days -= date_diff(end_date, start_date) + 1
    else:
        scheduled_days = get_scheduled_days(self.employee, start_date, end_date)
        for days in range(date_diff(end_date, start_date) + 1):
            date = add_days(end_date, -days)
            if not is_holiday(self.employee, date) and date not in scheduled_days:
                unmarked_days -= 1
    return unmarked_days

def calculate_lwp_ppl_and_absent_days(employee, start_date, end_date, holidays):
    lwp = 0
    absent = 0
    daily_wages_fraction_for_half_day = flt(frappe.db.get_value('Payroll Settings', None, 'daily_wages_fraction_for_half_day')) or 0.5
    leave_types = frappe.get_all('Leave Type', or_filters=[['is_ppl', '=', 1], ['is_lwp', '=', 1]], fields=['name', 'is_lwp', 'is_ppl', 'fraction_of_daily_salary_per_leave', 'include_holiday'])
    leave_type_map = {}
    for leave_type in leave_types:
        leave_type_map[leave_type.name] = leave_type
    attendances = frappe.db.sql('\n        SELECT attendance_date, status, leave_type\n        FROM `tabAttendance`\n        WHERE\n            status in ("Absent", "Half Day", "On leave")\n            AND employee = %s\n            AND docstatus = 1\n            AND attendance_date between %s and %s\n    ', values=(employee, start_date, end_date), as_dict=1)
    for d in attendances:
        if d.status in ('Half Day', 'On Leave') and d.leave_type and (d.leave_type not in leave_type_map.keys()):
            continue
        if formatdate(d.attendance_date, 'yyyy-mm-dd') in holidays:
            if d.status == 'Absent' or (d.leave_type and d.leave_type in leave_type_map.keys() and (not leave_type_map[d.leave_type]['include_holiday'])):
                continue
        if d.leave_type:
            fraction_of_daily_salary_per_leave = leave_type_map[d.leave_type]['fraction_of_daily_salary_per_leave']
        if d.status == 'Half Day':
            equivalent_lwp = 1 - daily_wages_fraction_for_half_day
            if d.leave_type in leave_type_map.keys() and leave_type_map[d.leave_type]['is_ppl']:
                equivalent_lwp *= fraction_of_daily_salary_per_leave if fraction_of_daily_salary_per_leave else 1
            lwp += equivalent_lwp
        elif d.status == 'On Leave' and d.leave_type and (d.leave_type in leave_type_map.keys()):
            equivalent_lwp = 1
            if leave_type_map[d.leave_type]['is_ppl']:
                equivalent_lwp *= fraction_of_daily_salary_per_leave if fraction_of_daily_salary_per_leave else 1
            lwp += equivalent_lwp
        elif d.status == 'Absent':
            absent += 1
    return (lwp, absent)

