functions.signature:
def get_valuation_rate_(item_code, warehouse, voucher_type, voucher_no, allow_zero_rate=False, currency=None, company=None, raise_error_if_no_rate=True, batch_no=None, serial_and_batch_bundle=None):
    if not company:
        company = frappe.get_cached_value('Warehouse', warehouse, 'company')
    last_valuation_rate = None
    if warehouse and batch_no and frappe.db.get_value('Batch', batch_no, 'use_batchwise_valuation'):
        last_valuation_rate = frappe.db.sql('\n            select sum(stock_value_difference) / sum(actual_qty)\n            from `tabStock Ledger Entry`\n            where\n                item_code = %s\n                AND warehouse = %s\n                AND batch_no = %s\n                AND is_cancelled = 0\n                AND NOT (voucher_no = %s AND voucher_type = %s)\n            ', (item_code, warehouse, batch_no, voucher_no, voucher_type))
    if not last_valuation_rate or last_valuation_rate[0][0] is None:
        last_valuation_rate = frappe.db.sql('select valuation_rate\n            from `tabStock Ledger Entry` force index (item_warehouse)\n            where\n                item_code = %s\n                AND warehouse = %s\n                AND valuation_rate >= 0\n                AND is_cancelled = 0\n                AND NOT (voucher_no = %s AND voucher_type = %s)\n            order by posting_date desc, posting_time desc, name desc limit 1', (item_code, warehouse, voucher_no, voucher_type))
        last_valuation_rate_ = frappe.db.sql("select valuation_rate\n                    from `tabStock Ledger Entry` force index (item_warehouse)\n                    where\n                        item_code = '{}'\n                        AND warehouse = '{}'\n                        AND valuation_rate >= 0\n                        AND is_cancelled = 0\n                        AND NOT (voucher_no = '{}' AND voucher_type = '{}')\n                    order by posting_date desc, posting_time desc, name desc limit 1".format(item_code, warehouse, voucher_no, voucher_type))
    if last_valuation_rate:
        return flt(last_valuation_rate[0][0])
    if not last_valuation_rate and last_valuation_rate_:
        return flt(last_valuation_rate_[0][0])
    valuation_rate = frappe.db.get_value('Item', item_code, 'valuation_rate')
    if not valuation_rate:
        valuation_rate = frappe.db.get_value('Item', item_code, 'standard_rate')
        if not valuation_rate:
            valuation_rate = frappe.db.get_value('Item Price', dict(item_code=item_code, buying=1, currency=currency), 'price_list_rate')
    if not allow_zero_rate and (not valuation_rate) and raise_error_if_no_rate and cint(erpnext.is_perpetual_inventory_enabled(company)):
        form_link = get_link_to_form('Item', item_code)
        message = _('Valuation Rate for the Item {0}, is required to do accounting entries for {1} {2}.').format(form_link, voucher_type, voucher_no)
        message += '<br><br>' + _('Here are the options to proceed:')
        solutions = '<li>' + _("If the item is transacting as a Zero Valuation Rate item in this entry, please enable 'Allow Zero Valuation Rate' in the {0} Item table.").format(voucher_type) + '</li>'
        solutions += '<li>' + _('If not, you can Cancel / Submit this entry') + ' {0} '.format(frappe.bold('after')) + _('performing either one below:') + '</li>'
        sub_solutions = '<ul><li>' + _('Create an incoming stock transaction for the Item.') + '</li>'
        sub_solutions += '<li>' + _('Mention Valuation Rate in the Item master.') + '</li></ul>'
        msg = message + solutions + sub_solutions + '</li>'
        frappe.throw(msg=msg, title=_('Valuation Rate Missing'))
    return valuation_rate

def get_duplicate_attendance_record(employee, attendance_date, shift, roster_type, name=None):
    overlapping_attendance = frappe.db.get_list('Attendance', filters={'employee': employee, 'attendance_date': attendance_date, 'shift': shift, 'roster_type': roster_type, 'docstatus': 1}, fields='*')
    return overlapping_attendance

def get_overlapping_shift_attendance(employee, attendance_date, shift, roster_type, name=None):
    if not shift:
        return {}
    attendance = frappe.qb.DocType('Attendance')
    query = frappe.qb.from_(attendance).select(attendance.name, attendance.shift).where((attendance.employee == employee) & (attendance.docstatus < 2) & (attendance.attendance_date == attendance_date) & (attendance.shift != shift) & (attendance.roster_type == roster_type))
    if name:
        query = query.where(attendance.name != name)
    overlapping_attendance = query.run(as_dict=True)
    if overlapping_attendance and has_overlapping_timings(shift, overlapping_attendance[0].shift):
        return overlapping_attendance[0]
    return {}

@frappe.whitelist()
def mark_single_attendance(emp, att_date, roster_type='Basic'):
    if not frappe.db.exists('Attendance', {'employee': emp, 'attendance_date': att_date, 'status': ['!=', 'Absent'], 'roster_type': roster_type, 'docstatus': 1}):
        open_leaves = frappe.db.sql(f"\n            SELECT name, employee FROM `tabLeave Application`\n            WHERE employee='{emp}' AND status='Open' AND '{att_date}' BETWEEN from_date AND to_date;\n        ", as_dict=1)
        if not open_leaves:
            employee = frappe.get_value('Employee', emp, {'name', 'holiday_list', 'employee_name'}, as_dict=1)
            status = 'Absent'
            comment = ''
            holiday_today = get_holiday_today(att_date)
            employee_schedule = frappe.db.get_value('Employee Schedule', {'employee': emp, 'date': att_date}, ['*'], as_dict=1)
            if employee_schedule:
                if employee_schedule.employee_availability == 'Day Off':
                    status = 'Day Off'
                    comment = f'Employee Schedule - {employee_schedule.name}'
                    create_single_attendance_record(frappe._dict({'employee': employee, 'attendance_date': att_date, 'status': status, 'comment': comment}))
                    return
            if holiday_today.get(employee.holiday_list):
                status = 'Holiday'
                comment = 'Holiday - ' + str(holiday_today.get(employee.holiday_list))
                create_single_attendance_record(frappe._dict({'employee': employee, 'attendance_date': att_date, 'status': status, 'comment': comment}))
                return
            elif employee_schedule:
                if employee_schedule.employee_availability == 'Working':
                    mark_for_shift_assignment(employee.name, att_date)
            else:
                mark_for_shift_assignment(employee.name, att_date)

@frappe.whitelist()
def mark_bulk_attendance(employee, from_date, to_date):
    date_range = pd.date_range(from_date, to_date)
    for date in date_range:
        mark_single_attendance(employee, date, roster_type='Basic')
        mark_for_shift_assignment(employee, date, roster_type='Over-Time')
    frappe.msgprint(f'Marked Attendance successfully for {employee} between {from_date} and {to_date}')

def mark_for_active_employees(from_date=None, to_date=None):
    if not (from_date and to_date):
        from_date, to_date = (add_days(getdate(), -1), add_days(getdate(), -1))
    active_employees = frappe.get_list('Employee', {'status': ['=', 'Active'], 'attendance_by_timesheet': 0}, ['name', 'employee_name', 'company', 'department', 'holiday_list'])
    for employee in active_employees:
        mark_bulk_attendance(employee.name, from_date, to_date)
    mark_attendance_for_unscheduled_employees(active_employees, from_date)
    remark_for_active_employees(from_date)

def remark_for_active_employees(from_date=None):
    if not from_date:
        from_date = today()
    absent_attendance = frappe.get_list('Attendance', {'attendance_date': from_date, 'status': 'Absent'}, '*')
    for i in absent_attendance:
        if i.shift_assignment:
            shift_assignment = frappe.get_doc('Shift Assignment', i.shift_assignment)
            checkins = frappe.get_list('Employee Checkin', {'shift_assignment': i.shift_assignment}, '*', order_by='time ASC')
            if checkins:
                ins = [d for d in checkins if d.log_type == 'IN']
                outs = [d for d in checkins if d.log_type == 'OUT']
                if ins:
                    ins = ins[0]
                if outs:
                    outs = outs[-1]
                    if ins:
                        if checkins[-1].log_type == 'IN':
                            outs = []
                if ins:
                    if (ins.time - shift_assignment.start_datetime).total_seconds() / (60 * 60) > 1:
                        status = 'Absent'
                        comment = f' Some hrs late, checkin in at {ins.time}'
                        working_hours = 1
                    elif ins and (not outs):
                        working_hours = (shift_assignment.end_datetime - ins.time).total_seconds() / (60 * 60)
                        status = 'Present'
                        comment = 'Checkin but no checkout record found or last log is checkin'
                        checkin = ins
                    elif ins and outs:
                        working_hours = (outs.time - ins.time).total_seconds() / (60 * 60)
                        status = 'Present'
                        comment = ''
                        checkin = ins
                        checkout = outs
                    create_single_attendance_record(frappe._dict({'status': status, 'comment': comment, 'attendance_date': from_date, 'working_hours': working_hours, 'checkin': ins, 'checkout': outs, 'shift_assignment': shift_assignment, 'employee': frappe.db.get_value('Employee', i.employee, ['name', 'employee_name', 'holiday_list'], as_dict=1), 'roster_type': shift_assignment.roster_type}))

def remark_absent_for_employees(employees, date):
    for emp in employees:
        mark_single_attendance(emp, date)

def mark_overtime_attendance(from_date, to_date):
    shift_assignments = frappe.db.get_list('Shift Assignment', filters={'start_date': from_date, 'end_date': to_date, 'roster_type': 'Over-Time', 'docstatus': 1}, fields=['employee'])
    for employee in frappe.db.get_list('Employee', {'name': ['IN', [i.employee for i in shift_assignments]], 'status': 'Active'}, 'name'):
        mark_for_shift_assignment(employee.name, from_date, roster_type='Over-Time')

def remark_attendance(start_date, end_date):
    try:
        shift_assignments = frappe.db.get_list('Shift Assignment', filters={'start_date': start_date, 'end_date': end_date}, fields='name, employee')
        attendances = frappe.db.get_list('Attendance', filters={'attendance_date': start_date, 'shift_assignment': ['IN', [i.name for i in shift_assignments]], 'docstatus': 1}, fields='name, employee')
        missing_attendances = [i.employee for i in shift_assignments if not i.employee in [x.employee for x in attendances]]
        for employee in missing_attendances:
            mark_bulk_attendance(employee, start_date, start_date)
    except:
        frappe.log_error(frappe.get_traceback(), 'Remark Attendance')

