            self.db_set('day_off_ot', day_off_ot)

def before_save(self):
    if not self.shift_assignment and self.status == 'Present':
        shift_assignment = frappe.db.get_value('Shift Assignment', {'employee': self.employee, 'start_date': self.attendance_date, 'status': 'Active', 'roster_type': 'Basic', 'docstatus': 1}, ['*'], as_dict=1)
        if shift_assignment:
            self.shift_assignment = shift_assignment.name
            self.shift = shift_assignment.shift_type
            self.operations_shift = shift_assignment.shift
            self.site = shift_assignment.site
    if self.attendance_request and (not self.working_hours) and (not self.status in ['Holiday', 'Day Off', 'Absent']):
        self.working_hours = frappe.db.get_value('Shift Type', self.shift_type, 'duration')

def validate_update_after_submit(self):
    db_values = frappe.get_doc(self.doctype, self.name).as_dict()
    for key in self.as_dict():
        df = self.meta.get_field(key)
        db_value = db_values.get(key)
        if key in ['status', 'working_hours'] and 'Payroll Operator' in frappe.get_roles():
            df.allow_on_submit = 1
        if df and (not df.allow_on_submit) and (self.get(key) or db_value):
            if df.fieldtype in table_fields:
                self_value = len(self.get(key))
                db_value = len(db_value)
            else:
                self_value = self.get_value(key)
            if isinstance(self_value, datetime.timedelta) and isinstance(db_value, datetime.time):
                db_value = datetime.timedelta(hours=db_value.hour, minutes=db_value.minute, seconds=db_value.second, microseconds=db_value.microsecond)
            if self_value != db_value:
                frappe.throw(_('{0} Not allowed to change {1} after submission from {2} to {3}').format(f'Row #{self.idx}:' if self.get('parent') else '', frappe.bold(_(df.label)), frappe.bold(db_value), frappe.bold(self_value)), frappe.UpdateAfterSubmitError, title=_('Cannot Update After Submit'))

def validate_duplicate_record(self):
    duplicate = get_duplicate_attendance_record(self.employee, self.attendance_date, self.shift, self.roster_type, self.name)
    for d in duplicate:
        if d.roster_type == self.roster_type:
            frappe.throw(_('Attendance for employee {0} is already marked for the date {1}: {2} : {3}').format(frappe.bold(self.employee), frappe.bold(self.attendance_date), get_link_to_form('Attendance', d.name), self.roster_type), title=_('Duplicate Attendance'), exc=DuplicateAttendanceError)

