        frappe.get_doc('Additional Salary', {'ref_doctype': self.doctype, 'ref_docname': self.name}).delete()

def mark_shift_attendance(self):
    if self.attendance_type:
        client_shifts = frappe.db.sql(f"\n                SELECT sa.* FROM `tabShift Assignment` sa\n                JOIN `tabOperations Role` op ON sa.operations_role=op.name\n                WHERE sa.is_replaced = 0\n                AND sa.start_date='{self.start.date()}'\n                AND op.attendance_by_client=1 AND op.docstatus=1\n                ;\n            ", as_dict=1)
        for i in client_shifts:
            self.create_attendance(frappe._dict({**i, **{'status': 'On Hold', 'dt': 'Shift Assignment'}}))
        shifts = frappe.db.sql(f"\n                SELECT sa.* FROM `tabShift Assignment` sa\n                JOIN `tabOperations Role` op ON sa.operations_role=op.name\n                WHERE sa.is_replaced = 0\n                AND sa.start_date='{self.start.date()}'\n                AND op.attendance_by_client=0 AND op.status='Active'\n            ", as_dict=1)
        non_shifts = frappe.db.sql(f"\n                SELECT sa.* FROM `tabShift Assignment` sa\n                JOIN `tabEmployee` e ON sa.employee=e.name\n                WHERE sa.is_replaced = 0\n                AND sa.end_datetime BETWEEN '{self.start}' AND  '{self.end}'\n                AND e.shift_working=0", as_dict=1)
        shifts.extend(non_shifts)
    else:
        client_shifts = frappe.db.sql(f"\n                SELECT sa.* FROM `tabShift Assignment` sa\n                JOIN `tabOperations Role` op ON sa.operations_role=op.name\n                WHERE sa.is_replaced = 0\n                AND sa.end_datetime BETWEEN '{self.start}' AND  '{self.end}'\n                AND op.attendance_by_client=1 AND op.status='Active'\n                ;\n                ", as_dict=1)
        for i in client_shifts:
            self.create_attendance(frappe._dict({**i, **{'status': 'On Hold', 'dt': 'Shift Assignment'}}))
        shifts = frappe.db.sql(f"\n                SELECT sa.* FROM `tabShift Assignment` sa\n                JOIN `tabOperations Role` op ON sa.operations_role=op.name\n                WHERE sa.is_replaced = 0\n                AND sa.end_datetime BETWEEN '{self.start}' AND  '{self.end}'\n                AND op.attendance_by_client=0 AND op.status='Active'\n            ", as_dict=1)
        non_shifts = frappe.db.sql(f"\n                SELECT sa.* FROM `tabShift Assignment` sa\n                JOIN `tabEmployee` e ON sa.employee=e.name\n                WHERE sa.is_replaced = 0\n                AND sa.end_datetime BETWEEN '{self.start}' AND  '{self.end}'\n                AND e.shift_working=0", as_dict=1)
        shifts.extend(non_shifts)
    if shifts:
        existing_attendance = frappe.get_list('Attendance', {'attendance_date': getdate(self.start), 'shift_assignment': ['in', [i.name for i in shifts]], 'status': ['IN', ['Present', 'Holiday', 'On Leave', 'Work From Home', 'On Hold', 'Day Off']]}, pluck='employee')
        checkins = self.get_checkins(tuple([i.name for i in shifts]) if len(shifts) > 1 else (shifts[0].name, ''))
        if checkins:
            checked_in_employees = [i.employee for i in checkins]
            no_checkins = [i for i in shifts if not i.employee in checked_in_employees]
            if no_checkins:
                for i in no_checkins:
                    if i.employee not in existing_attendance:
                        try:
                            record = frappe._dict({**dict(i), **{'status': 'Absent', 'comment': 'No checkin record found', 'working_hours': 0, 'dt': 'Shift Assignment'}})
                            self.create_attendance(record)
                        except:
                            frappe.log_error(message=frappe.get_traceback(), title=f'Error Marking Attendance for {i.employee}')
            if checkins:
                for i in checkins:
                    if i.earliest_time and isinstance(i.shift_actual_start, p_datetime):
                        if not frappe.db.exists('Attendance', {'employee': i.employee, 'attendance_date': i.shift_actual_start.date(), 'roster_type': i.roster_type, 'status': ['IN', ['Present', 'On Leave', 'Holiday', 'Day Off', 'On Hold', 'Work From Home']]}):
                            total_hours = (i.shift_actual_end - i.shift_actual_start).total_seconds() / (60 * 60)
                            i.early_exit = self.check_early_exit(i)
                            half_hour = total_hours / 2
                            working_hours = 0
                            status = 'Absent'
                            comment = ''
                            if (i.earliest_time - i.shift_actual_end).total_seconds() / (60 * 60) > half_hour:
                                status = 'Absent'
                                comment = f' Checked in late, checkin in at {i.earliest_time}'
                            elif i.earliest_time and i.latest_time:
                                working_hours = (i.latest_time - i.earliest_time).total_seconds() / (60 * 60)
                                if working_hours < half_hour:
                                    status = 'Absent'
                                    comment = f'Worked less than 50% of {total_hours}hrs.'
                                else:
                                    status = 'Present'
                                    comment = ''
                            elif i.earliest_time and (not i.latest_time):
                                working_hours = (i.shift_actual_end - i.earliest_time).total_seconds() / (60 * 60)
                                if working_hours < half_hour:
                                    status = 'Absent'
                                    comment = f'Worked less than 50% of {total_hours}hrs.'
                                else:
                                    status = 'Present'
                                    comment = ''
                            try:
                                self.create_attendance(frappe._dict({**dict(i), **{'status': status, 'comment': comment, 'working_hours': working_hours, 'dt': 'Employee Checkin'}}))
                            except Exception as e:
                                pass

def check_early_exit(self, checkin: dict) -> bool:
    """
            Validates the presence of a checkin record created after the last checkout record if
            the last checkout record  was set as a early exit

        """
    if checkin:
        in_name = checkin.get('in_name')
        out_name = checkin.get('out_name')
        if in_name and out_name:
            early_exit_doc = frappe.db.get_value('Employee Checkin', {'name': out_name, 'early_exit': 1, 'log_type': 'OUT'}, ['time'], as_dict=1)
            if early_exit_doc:
                check = frappe.db.sql('\n                        SELECT name FROM `tabEmployee Checkin`\n                        WHERE shift_assignment = %s\n                        AND  log_type =  %s\n                        AND time > %s\n                        ', (checkin.shift_assignment, 'IN', early_exit_doc.time), as_dict=1)
                return not bool(check)
    return False

def mark_day_off(self):
    days_off = frappe.get_list('Employee Schedule', {'date': self.start.date(), 'employee_availability': 'Day Off', 'is_replaced': 0}, '*')
    for i in days_off:
        try:
            if not frappe.db.exists('Attendance', {'employee': i.employee, 'attendance_date': i.date, 'roster_type': i.roster_type, 'status': ['IN', ['Present', 'On Leave', 'Holiday', 'Day Off', 'On Hold', 'Work From Home']]}):
                record = frappe._dict({**dict(i), **{'status': 'Day Off', 'comment': f'Employee Schedule - {i.name}', 'dt': 'Employee Schedule'}})
                self.create_attendance(record)
        except Exception as e:
            pass

def create_attendance(self, record, attendace_type=None):
    try:
        _date = None
        if record.shift_actual_start:
            _date = record.shift_actual_start.date()
        elif record.date:
            _date = record.date
        else:
            _date = record.start_date
        try:
            frappe.db.sql(f'\n                    DELETE FROM `tabAttendance` WHERE employee="{record.employee}" AND\n                    attendance_date="{_date}"\n                    AND roster_type="{record.roster_type}"\n                ')
        except:
            pass
        frappe.db.commit()
        doc = frappe._dict({})
        doc.doctype = 'Attendance'
        doc.employee = record.employee
        doc.status = record.status
        doc.attendance_date = _date
        if record.shift_assignment:
            doc.shift_assignment = record.shift_assignment
            doc.shift = record.shift_type
            doc.operations_shift = record.operations_shift
            doc.site = record.site
        if record.dt == 'Shift Assignment':
            doc.shift_assignment = record.name
            doc.shift = record.shift_type
            doc.operations_shift = record.shift
            doc.site = record.site
            doc.custom_employment_type = record.custom_employment_type
        if record.dt == 'Employee Schedule':
            doc.custom_employment_type = record.employment_type
        if record.dt == 'Employee Checkin':
            doc.custom_employment_type = frappe.db.get_value('Employee', doc.employee, 'employment_type')
        if record.late_entry:
            doc.late_entry = record.late_entry
        if record.early_exit:
            doc.early_exit = record.early_exit
        if record.working_hours:
            doc.working_hours = record.working_hours
        if record.roster_type:
            doc.roster_type = record.roster_type
        if record.comment:
            doc.comment = record.comment
        doc = frappe.get_doc(doc)
        doc.status = record.status
        doc.flags.ignore_validate = True
        doc.save()
        doc.db_set('docstatus', 1)
        if record.dt == 'Employee Checkin':
            if record.in_name:
                frappe.db.set_value('Employee Checkin', record.in_name, 'attendance', doc.name)
            if record.out_name:
                frappe.db.set_value('Employee Checkin', record.out_name, 'attendance', doc.name)
        frappe.db.commit()
    except Exception as e:
        frappe.log_error(message=frappe.get_traceback(), title=f'Hourly Attendance Marking - {str(e)}')

