@frappe.whitelist()
def get_start_end_dates(payroll_frequency, start_date=None, company=None):
    """Returns dict of start and end dates for given payroll frequency based on start_date"""
    start_date, end_date = (None, None)
    if payroll_frequency == 'Monthly':
        date = frappe.db.get_single_value('HR and Payroll Additional Settings', 'payroll_date')
        year = getdate().year - 1 if getdate().day < cint(date) and getdate().month == 1 else getdate().year
        month = getdate().month if getdate().day >= cint(date) else getdate().month - 1
        payroll_date = datetime(year, month, cint(date)).strftime('%Y-%m-%d')
        start_date = add_to_date(payroll_date, months=-1)
        end_date = add_to_date(payroll_date, days=-1)
    return frappe._dict({'start_date': start_date, 'end_date': end_date})

def get_employee_list(filters: frappe._dict, searchfield=None, search_string=None, fields: list[str] | None=None, as_dict=True, limit=None, offset=None, ignore_match_conditions=False) -> list:
    sal_struct = get_salary_structure(filters.company, filters.currency, filters.salary_slip_based_on_timesheet, filters.payroll_frequency)
    if not sal_struct:
        return []
    emp_list = get_filtered_employees(sal_struct, filters, searchfield, search_string, fields, as_dict=as_dict, limit=limit, offset=offset, ignore_match_conditions=ignore_match_conditions)
