def get_filtered_employees(sal_struct, filters, searchfield=None, search_string=None, fields=None, as_dict=False, limit=None, offset=None, ignore_match_conditions=False) -> list:
    SalaryStructureAssignment = frappe.qb.DocType('Salary Structure Assignment')
    Employee = frappe.qb.DocType('Employee')
    Attendance = frappe.qb.DocType('Attendance')
    attendance_sub_query = None
    if filters.payroll_type == 'Basic':
        attendance_sub_query = Employee.employee.notin(frappe.qb.from_(Attendance).select(Attendance.employee).where(Attendance.attendance_date[filters.start_date:filters.end_date] & (Attendance.status == 'On Hold') & (Attendance.roster_type == filters.payroll_type)))
    elif filters.payroll_type == 'Over-Time':
        attendance_sub_query = Employee.employee.isin(frappe.qb.from_(Attendance).select(Attendance.employee).where(Attendance.attendance_date[filters.start_date:filters.end_date] & (Attendance.status != 'On Hold') & (Attendance.roster_type == filters.payroll_type)))
    query = frappe.qb.from_(Employee).join(SalaryStructureAssignment).on(Employee.name == SalaryStructureAssignment.employee).where((SalaryStructureAssignment.docstatus == 1) & Employee.status.isin(['Active', 'Vacation']) & (Employee.company == filters.company) & ((Employee.date_of_joining <= filters.end_date) | Employee.date_of_joining.isnull()) & ((Employee.relieving_date >= filters.start_date) | Employee.relieving_date.isnull()) & SalaryStructureAssignment.salary_structure.isin(sal_struct) & (SalaryStructureAssignment.payroll_payable_account == filters.payroll_payable_account) & (filters.end_date >= SalaryStructureAssignment.from_date) & attendance_sub_query)
    query = set_fields_to_select(query, fields)
    query = set_searchfield(query, searchfield, search_string, qb_object=Employee)
    query = set_filter_conditions(query, filters, qb_object=Employee)
    if not ignore_match_conditions:
        query = set_match_conditions(query=query, qb_object=Employee)
    if limit:
        query = query.limit(limit)
    if offset:
        query = query.offset(offset)
    return query.run(as_dict=as_dict)

def set_filter_conditions(query, filters, qb_object):
    """Append optional filters to employee query"""
    if filters.get('employees'):
        query = query.where(qb_object.name.notin(filters.get('employees')))
    if filters.get('project'):
        query = query.where(qb_object.project.isin(filters.get('project')))
    for fltr_key in ['branch', 'department', 'designation', 'grade', 'custom_payroll_cycle_start_date', 'custom_payroll_cycle_end_date']:
        if filters.get(fltr_key):
            query = query.where(qb_object[fltr_key] == filters[fltr_key])
    return query

def set_bank_details(self, employee_details):
    """This Funtion Sets the bank Details of an employee. The data is fetched from Bank Account Doctype.

	Args:
		employee_details (dict): Employee Details Child Table.

	Returns:
		employee_details ([dict): Sets the bank account IBAN code and Bank Code.
	"""
    employee_missing_detail = []
    for employee in employee_details:
        try:
            bank_account = frappe.db.get_value('Bank Account', {'party': employee.employee}, ['iban', 'bank', 'bank_account_no'])
            salary_mode = frappe.db.get_value('Employee', {'name': employee.employee}, ['salary_mode'])
            if bank_account:
                iban, bank, bank_account_no = bank_account
            else:
                iban, bank, bank_account_no = (None, None, None)
            if not salary_mode:
                employee_missing_detail.append(frappe._dict({'employee': employee.employee, 'salary_mode': '', 'issue': 'No salary mode'}))
            elif salary_mode == 'Bank' and bank is None:
                employee_missing_detail.append(frappe._dict({'employee': employee.employee, 'salary_mode': salary_mode, 'issue': 'No bank account'}))
            elif salary_mode == 'Bank' and bank_account_no is None:
                employee_missing_detail.append(frappe._dict({'employee': employee.employee, 'salary_mode': salary_mode, 'issue': 'No account no.'}))
            employee.salary_mode = salary_mode
            employee.iban_number = iban or bank_account_no
            bank_code = frappe.db.get_value('Bank', {'name': bank}, ['bank_code'])
            employee.bank_code = bank_code
        except Exception as e:
            frappe.log_error(str(e), 'Payroll Entry')
            frappe.throw(str(e))
    if len(employee_missing_detail) > 0:
        missing_detail = []
        for i in employee_missing_detail:
            missing_detail.append({'employee': i.employee, 'salary_mode': i.salary_mode, 'issue': i.issue})
        mpi_exists = frappe.db.exists('Missing Payroll Information', {'payroll_entry': self.name})
        if mpi_exists:
            mpi = frappe.get_doc('Missing Payroll Information', mpi_exists)
            for i in missing_detail:
                mpi.append('missing_payroll_information_detail', i)
            mpi.save(ignore_permissions=True)
            frappe.db.commit()
        else:
            mpi = frappe.get_doc({'doctype': 'Missing Payroll Information', 'payroll_entry': self.name, 'missing_payroll_information_detail': missing_detail}).insert(ignore_permissions=True)
            frappe.db.commit()
        message = frappe.render_template('one_fm/api/doc_methods/templates/payroll/bank_issue.html', context={'employees': employee_missing_detail, 'mpi': mpi})
        frappe.throw(_(message))
    return employee_details

