def get_salary_component_total(self, component_type=None, employee_wise_accounting_enabled=False):
    salary_components = self.get_salary_components(component_type)
    if salary_components:
        component_dict = {}
        for item in salary_components:
            if not self.should_add_component_to_accrual_jv(component_type, item):
                continue
            department = frappe.db.get_value('Employee', item.employee, 'department')
            employee_cost_centers = self.get_payroll_cost_centers_for_employee(item.employee, item.salary_structure)
            employee_advance = self.get_advance_deduction(component_type, item)
            for cost_center, percentage in employee_cost_centers.items():
                amount_against_cost_center = flt(item.amount) * percentage / 100
                if employee_advance:
                    self.add_advance_deduction_entry(item, amount_against_cost_center, cost_center, employee_advance)
                else:
                    key = (item.salary_component, cost_center, department)
                    component_dict[key] = component_dict.get(key, 0) + amount_against_cost_center
                if employee_wise_accounting_enabled:
                    self.set_employee_based_payroll_payable_entries(component_type, item.employee, amount_against_cost_center)
        account_details = self.get_account(component_dict=component_dict)
        return account_details

def get_account(self, component_dict=None):
    account_dict = {}
    for key, amount in component_dict.items():
        component, cost_center, department = key
        account = self.get_salary_component_account(component, department)
        accounting_key = (account, cost_center)
        account_dict[accounting_key] = account_dict.get(accounting_key, 0) + amount
    return account_dict

def get_salary_component_account(self, salary_component, department):
    account = frappe.db.get_value('Salary Component Account', {'parent': salary_component, 'company': self.company, 'custom_department': department}, 'account', cache=True)
    if not account:
        account = frappe.db.get_value('Salary Component Account', {'parent': salary_component, 'company': self.company}, 'account', cache=True)
    if not account:
        frappe.throw(_('Please set account in Salary Component {0}').format(get_link_to_form('Salary Component', salary_component)))
    return account

@frappe.whitelist()
def fill_employee_details(self):
