        update_rfp_status(self.one_fm_request_for_purchase)

def update_purchased_quantities(self):
    if not self.one_fm_request_for_purchase:
        return
    purchase_orders = frappe.db.get_list('Purchase Order', filters={'one_fm_request_for_purchase': self.one_fm_request_for_purchase, 'docstatus': 1}, pluck='name')
    request_for_material = frappe.db.get_value('Request for Purchase', {'name': self.one_fm_request_for_purchase}, 'request_for_material')
    for obj in self.items:
        po_items = frappe.db.get_all('Purchase Order Item', filters={'parent': ['in', purchase_orders], 'item_code': obj.item_code, 'parentfield': 'items'}, fields=['stock_qty', 'qty', 'uom', 'stock_uom', 'conversion_factor'])
        total_purchased_stock_qty = 0
        for po_item in po_items:
            if po_item.stock_qty and po_item.stock_qty > 0:
                total_purchased_stock_qty += po_item.stock_qty
            elif po_item.uom and po_item.stock_uom and (po_item.uom != po_item.stock_uom) and po_item.conversion_factor:
                total_purchased_stock_qty += (po_item.qty or 0) * (po_item.conversion_factor or 1)
            else:
                total_purchased_stock_qty += po_item.qty or 0
        update_purchased_qty(total_purchased_stock_qty, self.one_fm_request_for_purchase, obj.item_code, 'Request for Purchase Item', 'purchased_quantity')
        if request_for_material:
            update_purchased_qty(total_purchased_stock_qty, request_for_material, obj.item_code, 'Request for Material Item', 'ordered_qty')

def update_ordered_and_pending_quantities(self):
    if not self.one_fm_request_for_purchase:
        return
    purchase_orders = frappe.db.get_list('Purchase Order', filters={'one_fm_request_for_purchase': self.one_fm_request_for_purchase, 'docstatus': 1}, pluck='name')
    rfp_items = frappe.db.get_all('Request for Purchase Quotation Item', filters={'parent': self.one_fm_request_for_purchase}, fields=['name', 'item_code', 'qty', 'stock_qty', 'uom', 'stock_uom', 'conversion_factor'])
    for rfp_item in rfp_items:
        po_items = frappe.db.get_all('Purchase Order Item', filters={'parent': ['in', purchase_orders], 'item_code': rfp_item.item_code, 'parentfield': 'items'}, fields=['stock_qty', 'qty', 'uom', 'stock_uom', 'conversion_factor'])
        total_ordered_stock_qty = 0
        for po_item in po_items:
            if po_item.stock_qty:
                total_ordered_stock_qty += po_item.stock_qty
            elif po_item.uom and po_item.stock_uom and (po_item.uom != po_item.stock_uom):
                conversion_factor = po_item.conversion_factor or 1
                total_ordered_stock_qty += (po_item.qty or 0) * conversion_factor
            else:
                total_ordered_stock_qty += po_item.qty or 0
        rfp_qty_in_stock_uom = rfp_item.stock_qty if rfp_item.stock_qty else rfp_item.qty
        pending_qty = max(0, rfp_qty_in_stock_uom - total_ordered_stock_qty)
        frappe.db.set_value('Request for Purchase Quotation Item', rfp_item.name, {'ordered_qty': total_ordered_stock_qty, 'pending_qty': pending_qty})
    frappe.db.commit()

functions.signature:
def get_workflow_assignment_rule_description(doc, user):
    doctype = doc.get('doctype')
    message_html = get_assignment_rule_description(doctype)
    workflow = get_workflow_name(doctype)
    if workflow:
        transitions = get_next_possible_transitions(workflow, get_doc_workflow_state(doc), doc)
        action_details = []
        for transition in transitions:
            action_details.append(frappe._dict({'action_name': transition.action, 'action_link': get_confirm_workflow_action_url(doc, transition.action, user)}))
        if action_details and len(action_details) > 0:
            message_html += '<div>'
            for action in action_details:
                message_html += '<a href={0} class="btn btn-primary btn-action" style="margin-right: 10px;">{1}</a>'.format(action.action_link, action.action_name)
            message_html += '</div>'
    return message_html

def do_assignment(self, doc):
    if frappe.session.user == 'Guest':
        frappe.set_user('Administrator')
    assign_to.clear(doc.get('doctype'), doc.get('name'))
    user = self.get_user(doc)
    if user:
        description = self.description
        if self.is_assignment_rule_with_workflow:
            description = get_workflow_assignment_rule_description(doc, user)
        assign_to.add(dict(assign_to=[user], doctype=doc.get('doctype'), name=doc.get('name'), description=frappe.render_template(description, doc), assignment_rule=self.name, notify=True, date=doc.get(self.due_date_based_on) if self.due_date_based_on else None))
        self.db_set('last_user', user)
        return True
    return False

def get_user(self, doc):
    """
	Get the next user for assignment
	"""
    if self.rule == 'Round Robin':
        return self.get_user_round_robin()
    elif self.rule == 'Load Balancing':
        return self.get_user_load_balancing()
    elif self.rule == 'Based on Field':
        return self.get_user_based_on_field(doc)
    elif self.rule == 'Based on Process Task':
        return self.get_user_based_on_process_task()

def validate_active_staff(doc, event):
    emp_details = frappe.get_value('Employee', doc.employee, ['status', 'relieving_date'], as_dict=1)
