def update_attendance_recods(self):
    if self.status != 'Approved':
        return
    holiday_dates = []
    if self.leave_type == 'Annual Leave':
        holidays = get_holidays_for_employee(employee=self.employee, start_date=self.from_date, end_date=self.to_date, only_non_weekly=True)
        holiday_dates = [cstr(h.holiday_date) for h in holidays]
    for dt in daterange(getdate(self.from_date), getdate(self.to_date)):
        date = dt.strftime('%Y-%m-%d')
        attendance_name = frappe.db.exists('Attendance', dict(employee=self.employee, attendance_date=date, docstatus=('!=', 2)))
        if date in holiday_dates:
            if attendance_name:
                attendance = frappe.get_doc('Attendance', attendance_name)
                attendance.flags.ignore_permissions = True
                if attendance.docstatus == 1:
                    attendance.db_set('status', 'Holiday')
                    frappe.db.commit()
            else:
                self.create_or_update_attendance(attendance_name, date, 'Holiday')
        else:
            self.create_or_update_attendance(attendance_name, date, 'On Leave')
    frappe.msgprint(_('Attendance are created for the leave Appication {0}!'.format(self.name)), alert=True)

def remove_assignment(attendance_check):
    open_todo = get_open_todos('Attendance Check', attendance_check)
    if open_todo:
        for each in open_todo:
            remove('Attendance Check', attendance_check, each.allocated_to, ignore_permissions=1)

@frappe.whitelist()
def get_leave_details(employee, date):
    allocation_records = get_leave_allocation_records(employee, date)
    leave_allocation = {}
    precision = cint(frappe.db.get_single_value('System Settings', 'float_precision', cache=True))
    for d in allocation_records:
        allocation = allocation_records.get(d, frappe._dict())
        remaining_leaves = get_leave_balance_on(employee, d, date, to_date=allocation.to_date, consider_all_leaves_in_the_allocation_period=True)
        end_date = allocation.to_date
        leaves_taken = get_leaves_for_period(employee, d, allocation.from_date, end_date) * -1
        leaves_pending = get_leaves_pending_approval_for_period(employee, d, allocation.from_date, end_date)
        expired_leaves = allocation.total_leaves_allocated - (remaining_leaves + leaves_taken)
        leave_allocation[d] = {'total_leaves': flt(allocation.total_leaves_allocated, precision), 'expired_leaves': flt(expired_leaves, precision) if expired_leaves > 0 else 0, 'leaves_taken': flt(leaves_taken, precision), 'leaves_pending_approval': flt(leaves_pending, precision), 'remaining_leaves': flt(remaining_leaves, precision)}
    lwp = frappe.get_list('Leave Type', filters={'is_lwp': 1}, pluck='name')
    return {'leave_allocation': leave_allocation, 'leave_approver': get_leave_approver(employee), 'lwps': lwp}

@frappe.whitelist()
def get_leave_approver(employee):
