            existing_assignment = frappe.get_all('ToDo', {'allocated_to': self.leave_approver, 'reference_name': self.name})
            if not existing_assignment:
                frappe.get_doc({'doctype': 'ToDo', 'allocated_to': self.leave_approver, 'reference_type': 'Leave Application', 'reference_name': self.name, 'description': f'Please note that leave application {self.name} is awaiting your approval', 'priority': 'Medium', 'status': 'Open', 'date': nowdate(), 'assigned_by': frappe.session.user}).insert(ignore_permissions=True)
