def validate_dates(self):
    if frappe.db.get_single_value('HR Settings', 'restrict_backdated_leave_application'):
        if self.from_date and getdate(self.from_date) < getdate(self.posting_date):
            allowed_role = frappe.db.get_single_value('HR Settings', 'role_allowed_to_create_backdated_leave_application')
            user = frappe.get_doc('User', frappe.session.user)
            user_roles = [d.role for d in user.roles]
            if not allowed_role:
                frappe.throw(_('Backdated Leave Application is restricted. Please set the {} in {}').format(frappe.bold('Role Allowed to Create Backdated Leave Application'), get_link_to_form('HR Settings', 'HR Settings')))
            if allowed_role and allowed_role not in user_roles:
                frappe.throw(_('Only users with the {0} role can create backdated leave applications').format(allowed_role))
    if self.from_date and self.to_date and (getdate(self.to_date) < getdate(self.from_date)):
        frappe.throw(_('To date cannot be before from date'))
    if self.half_day and self.half_day_date:
        half_day_date = getdate(self.half_day_date)
        if half_day_date < getdate(self.from_date) or half_day_date > getdate(self.to_date):
            frappe.throw(_('Half Day Date should be between From Date and To Date'))
