        for i in attendance_range:
            if getdate() > i:
                if frappe.db.exists('Attendance', {'employee': self.employee, 'attendance_date': str(i), 'docstatus': 1}):
                    frappe.db.sql(f"""\n                            UPDATE `tabAttendance` SET status='Absent', comment="Leave Appication {self.name} Rejected"\n                            WHERE attendance_date='{str(i)}' and employee='{self.employee}'\n                        """)
                else:
                    frappe.get_doc({'doctype': 'Attendance', 'employee': self.employee, 'attendance_date': str(i), 'roster_type': 'Basic', 'status': 'Absent'}).submit()
                frappe.db.commit()
    if self.status == 'Approved':
        today = getdate()
        if self.custom_reliever_:
            employee = frappe.get_doc('Employee', self.employee)
