@frappe.whitelist()
def make_purchase_receipt(source_name, target_doc=None, args=None):
    if args is None:
        args = {}
    if isinstance(args, str):
        args = json.loads(args)

    def update_item(obj, target, source_parent):
        target.qty = flt(obj.qty) - flt(obj.received_qty)
        target.received_qty = flt(obj.qty) - flt(obj.received_qty)
        target.stock_qty = (flt(obj.qty) - flt(obj.received_qty)) * flt(obj.conversion_factor)
        target.amount = (flt(obj.qty) - flt(obj.received_qty)) * flt(obj.rate)
        target.base_amount = (flt(obj.qty) - flt(obj.received_qty)) * flt(obj.rate) * flt(source_parent.conversion_rate)
        if target.get('custom_refundable'):
            target.margin_type = None
            target.margin_rate_or_amount = 0
            target.rate_with_margin = 0

    def select_item(d):
        filtered_items = args.get('filtered_children', [])
        child_filter = d.name in filtered_items if filtered_items else True
        return child_filter
    doc = get_mapped_doc('Purchase Invoice', source_name, {'Purchase Invoice': {'doctype': 'Purchase Receipt', 'validation': {'docstatus': ['=', 1]}}, 'Purchase Invoice Item': {'doctype': 'Purchase Receipt Item', 'field_map': {'name': 'purchase_invoice_item', 'parent': 'purchase_invoice', 'bom': 'bom', 'purchase_order': 'purchase_order', 'po_detail': 'purchase_order_item', 'material_request': 'material_request', 'material_request_item': 'material_request_item', 'wip_composite_asset': 'wip_composite_asset', 'custom_refundable': 'custom_refundable', 'margin_type': 'margin_type', 'margin_rate_or_amount': 'margin_rate_or_amount'}, 'postprocess': update_item, 'condition': lambda doc: abs(doc.received_qty) < abs(doc.qty) and select_item(doc)}, 'Purchase Taxes and Charges': {'doctype': 'Purchase Taxes and Charges'}}, target_doc)
    return doc

