def is_holiday(holiday_list, date=None):
    """Returns true if the given date is a holiday in the given holiday list"""
    if date is None:
        date = today()
    if holiday_list:
        return bool(frappe.db.exists('Holiday', {'parent': holiday_list, 'holiday_date': date}, cache=True))
    else:
        return False

