                        frappe.db.set_value('Employee Schedule', existing_schedule.name, update_data)
                    else:
                        create_employee_schedule_from_request(doc, date)
                if date == today():
                    shift_assignment = frappe._dict({'company': doc.company, 'operations_shift': doc.operations_shift, 'roster_type': doc.roster_type, 'shift_type': doc.shift_type, 'employee': doc.employee, 'from_date': date, 'name': doc.name, 'check_in_site': doc.check_in_site, 'check_out_site': doc.check_out_site, 'operations_role': doc.operations_role})
                    create_shift_assignment_from_request(shift_assignment)
        elif day_off_ot:
            validate_day_of_ot(doc)
            shift_assignment = frappe.get_list('Shift Assignment', filters=[['employee', '=', doc.employee], ['start_date', 'between', [doc.from_date, doc.to_date]], ['roster_type', '=', 'Basic']], fields=['name'])
            if shift_assignment:
                update_shift_assignment(shift_assignment[0].name, doc, day_off_ot=day_off_ot)
            else:
                create_shift_assignment_from_request(doc, day_off_ot=day_off_ot)
        elif doc.purpose == 'Update Existing Assignment':
            if check_for_roster(doc):
                if doc.roster_type == 'Basic' and cstr(doc.from_date) <= cstr(getdate()) <= cstr(doc.to_date):
                    shift_assignemnt = frappe.get_list('Shift Assignment', filters=[['employee', '=', doc.employee], ['start_date', 'between', [doc.from_date, doc.to_date]], ['roster_type', '=', 'Basic']], fields=['name'])
                    if shift_assignemnt:
                        update_shift_assignment(shift_assignemnt[0].name, doc)
                if shift_worker == 1:
                    schedule_date_range = [str(i.date()) for i in pd.date_range(start=doc.from_date, end=doc.to_date)]
                    found_schedules_date = []
                    existing_schedules = frappe.db.sql(f""" SELECT name, date FROM `tabEmployee Schedule`\n                        WHERE employee="{doc.employee}" AND roster_type="{doc.roster_type}"\n                        AND date BETWEEN '{doc.from_date}' AND '{doc.to_date}' """, as_dict=1)
                    if existing_schedules:
                        for es in existing_schedules:
                            start_time, end_time = frappe.db.get_value('Shift Type', doc.shift_type, ['start_time', 'end_time'])
                            end_date = es.date
                            if start_time > end_time:
                                end_date = add_days(end_date, 1)
                            frappe.db.set_value('Employee Schedule', es.name, {'shift': doc.operations_shift, 'shift_type': doc.shift_type, 'start_datetime': f'{es.date} {start_time}', 'end_datetime': f'{end_date} {end_time}', 'operations_role': doc.operations_role, 'post_abbrv': role_abbr, 'employee_availability': 'Working', 'roster_type': doc.roster_type, 'department': doc.department, 'site': doc.site, 'reference_doctype': doc.doctype, 'reference_docname': doc.name})
                            found_schedules_date.append(str(es.date))
                    new_date_range = [i for i in schedule_date_range if not i in found_schedules_date]
                    if new_date_range:
                        for date in new_date_range:
                            if frappe.db.exists('Employee Schedule', {'date': date, 'employee': doc.employee, 'employee_availability': 'Day Off'}):
                                es = frappe.get_doc('Employee Schedule', {'date': date, 'employee': doc.employee, 'employee_availability': 'Day Off'})
                                start_time, end_time = frappe.db.get_value('Shift Type', doc.shift_type, ['start_time', 'end_time'])
                                end_date = es.date
                                if start_time > end_time:
                                    end_date = add_days(end_date, 1)
                                frappe.db.set_value('Employee Schedule', es.name, {'shift': doc.operations_shift, 'shift_type': doc.shift_type, 'start_datetime': f'{es.date} {start_time}', 'end_datetime': f'{end_date} {end_time}', 'operations_role': doc.operations_role, 'post_abbrv': role_abbr, 'employee_availability': 'Working', 'roster_type': doc.roster_type, 'department': doc.department, 'site': doc.site, 'reference_doctype': doc.doctype, 'reference_docname': doc.name})
