def is_employee_master(user: str) -> int:
    can_edit = 0
    employee_master_role = frappe.get_all('ONEFM Document Access Roles Detail', {'parent': 'ONEFM General Setting', 'parentfield': 'employee_master_role'}, ['role'])
    if employee_master_role:
