def calculate_amount_pay_back(uniform, returned_on=None):
    pay_back = 0
    if not returned_on:
        returned_on = getdate(today())
    qty_return = uniform.quantity - (uniform.returned or 0)
    if qty_return > 0 and getdate(uniform.expire_on) > getdate(returned_on):
        per_month_rate = qty_return * uniform.rate / month_diff(uniform.expire_on, uniform.issued_on)
        pay_back += per_month_rate * month_diff(uniform.expire_on, returned_on)
    return pay_back

def execute(filters=None):
    filters = frappe._dict(filters or {})
    include_uom = filters.get('include_uom')
    columns = get_columns()
    bin_list = get_bin_list(filters)
    item_map = get_item_map(filters.get('item_code'), include_uom)
    warehouse_company = {}
    data = []
    conversion_factors = []
    for bin in bin_list:
        item = item_map.get(bin.item_code)
        if not item:
            continue
        company = warehouse_company.setdefault(bin.warehouse, frappe.db.get_value('Warehouse', bin.warehouse, 'company'))
        if filters.brand and filters.brand != item.brand:
            continue
        elif filters.item_group and filters.item_group != item.item_group:
            continue
        elif filters.company and filters.company != company:
            continue
        re_order_level = re_order_qty = 0
        for d in item.get('reorder_levels'):
            if d.warehouse == bin.warehouse:
                re_order_level = d.warehouse_reorder_level
                re_order_qty = d.warehouse_reorder_qty
        shortage_qty = 0
        if (re_order_level or re_order_qty) and re_order_level > bin.projected_qty:
            shortage_qty = re_order_level - flt(bin.projected_qty)
        distributed = 0
        query = "\n\t\t\tselect\n\t\t\t\tui.quantity, ui.returned\n\t\t\tfrom\n\t\t\t\t`tabEmployee Uniform Item` ui, `tabEmployee Uniform` u\n\t\t\twhere\n\t\t\t\tui.parent=u.name and u.docstatus=1 and u.type='Issue' and ui.quantity > ui.returned and item = '{0}'\n\t\t"
        distribution_list = frappe.db.sql(query.format(item.name), as_dict=True)
        for distribution in distribution_list:
            distributed += distribution.quantity - distribution.returned
        data.append([item.name, item.description, item.item_group, item.stock_uom, bin.actual_qty + distributed, distributed, bin.actual_qty, bin.used_warehouse_qty])
        if include_uom:
            conversion_factors.append(item.conversion_factor)
    update_included_uom_in_report(columns, data, include_uom, conversion_factors)
    return (columns, data)

def get_bin_list(filters):
    conditions = []
    if filters.item_code:
        conditions.append("item_code = '%s' " % filters.item_code)
    if filters.warehouse:
        warehouse_details = frappe.db.get_value('Warehouse', filters.warehouse, ['lft', 'rgt'], as_dict=1)
        if warehouse_details:
            conditions.append(' exists (select name from `tabWarehouse` wh \t\t\t\twhere wh.lft >= %s and wh.rgt <= %s and bin.warehouse = wh.name)' % (warehouse_details.lft, warehouse_details.rgt))
    bin_list = frappe.db.sql('select item_code, warehouse, actual_qty, planned_qty, indented_qty,\n\t\tordered_qty, reserved_qty, reserved_qty_for_production, reserved_qty_for_sub_contract, projected_qty\n\t\tfrom tabBin bin {conditions} order by item_code, warehouse\n\t\t'.format(conditions=' where ' + ' and '.join(conditions) if conditions else ''), as_dict=1)
    used_warehouse_bin_list = get_used_uniform_qty()
    for bin in bin_list:
        if used_warehouse_bin_list:
            for used_bin in used_warehouse_bin_list:
                if used_bin.item_code == bin.item_code:
                    bin['used_warehouse_qty'] = used_bin.actual_qty
    return bin_list

def get_item_map(item_code, include_uom):
    """Optimization: get only the item doc and re_order_levels table"""
    condition = ''
    if item_code:
        condition = 'and item_code = {0}'.format(frappe.db.escape(item_code, percent=False))
    cf_field = cf_join = ''
    if include_uom:
        cf_field = ', ucd.conversion_factor'
        cf_join = 'left join `tabUOM Conversion Detail` ucd on ucd.parent=item.name and ucd.uom=%(include_uom)s'
    items = frappe.db.sql("\n\t\tselect item.name, item.item_name, item.description, item.item_group, item.brand, item.stock_uom{cf_field}\n\t\tfrom `tabItem` item\n\t\t{cf_join}\n\t\twhere item.is_stock_item = 1\n\t\tand item.disabled=0\n\t\t{condition}\n\t\tand (item.end_of_life > %(today)s or item.end_of_life is null or item.end_of_life='0000-00-00')\n\t\tand exists (select name from `tabBin` bin where bin.item_code=item.name)".format(cf_field=cf_field, cf_join=cf_join, condition=condition), {'today': today(), 'include_uom': include_uom}, as_dict=True)
    condition = ''
    if item_code:
        condition = 'where parent={0}'.format(frappe.db.escape(item_code, percent=False))
    reorder_levels = frappe._dict()
    for ir in frappe.db.sql('select * from `tabItem Reorder` {condition}'.format(condition=condition), as_dict=1):
        if ir.parent not in reorder_levels:
            reorder_levels[ir.parent] = []
        reorder_levels[ir.parent].append(ir)
    item_map = frappe._dict()
    for item in items:
        item['reorder_levels'] = reorder_levels.get(item.name) or []
        item_map[item.name] = item
    return item_map

