    data = fetch_data()
    for each in data:
        if each.name == self.name:
            setattr(self, '_table_fieldnames', [])
            for key, value in each.items():
                setattr(self, key, value)
                if key == 'release_notes':
                    docfield = self.meta.get_field(key)
