def notify_for_employee_docs_expiry():
    """
        Method to notify Onboarding officers about employee docs expiration
    """
    try:
        grd_settings = frappe.get_single('GRD Settings')
        recipients = list(set([grd_settings.default_grd_supervisor, grd_settings.default_grd_operator, grd_settings.default_grd_operator_pifss]))
        if not recipients:
            return
        notify_days_before = grd_settings.days_before_expiry_to_notify_supervisor or 15
        employees = get_employees_by_expiry_doc(notify_days_before)
        if employees:
            send_employee_doc_expiry_notification(employees, recipients)
    except Exception as e:
        frappe.log_error(str(e), 'Employee Docs Expiry')

def get_employees_by_expiry_doc(notify_days_before):
    target_expiry_date = add_days(today(), notify_days_before)
    expiry_fields = [('work_permit_expiry_date', 'Work Permit'), ('residency_expiry_date', 'Residency'), ('civil_id_expiry_date', 'Civil ID'), ('valid_upto', 'Passport')]
    employees_by_expiry = {}
    for expiry_field, expiry_doc in expiry_fields:
        employees_by_expiry[expiry_doc] = frappe.get_all('Employee', filters=[[expiry_field, '=', target_expiry_date], ['status', 'in', ['Active', 'Vacation']]], fields=['name', 'employee_name', expiry_field])
    return employees_by_expiry

def send_employee_doc_expiry_notification(employees_by_expiry, recipients):
    for expiring_doc in employees_by_expiry:
        for employee in employees_by_expiry[expiring_doc]:
            subject = f"Document Expiry - {employee['employee_name']}"
            header = f"{employee['employee_name']}'s {expiring_doc} is about to expire."
            message = f"Dear Onboarding Officer,<br><br>The following employee's {expiring_doc} is expiring on {str(add_days(today(), 30))}:<br><br>Employee Name: {employee['employee_name']}<br>Employee ID: {employee['name']}<br><br>Kindly take the necessary action."
            doc_link = get_url_to_form('Employee', employee['name'])
            for recipient in recipients:
                create_employee_doc_expiry_notification_log(subject, message, employee['name'], recipient)
                context = {'body_content': subject, 'description': message, 'document_type': 'Employee', 'document_name': employee['name'], 'doc_link': doc_link, 'header': header}
                msg = frappe.render_template('one_fm/templates/emails/notification_log.html', context=context)
