    if self.workflow_state not in ['Completed', 'Reschedule Requested']:
        return
    if not self.date_and_time_confirmation:
        frappe.throw(_('Date and Time Confirmation is required.'), title=_('Date and Time Confirmation Required'))
    if getdate(self.date_and_time_confirmation) > getdate(today()):
        frappe.throw(_('You are not allowed to action medical appointment before the appointment date.'), title=_('Appointment Date is in the future'))

def set_approver(self):
