        return
    if self.workflow_state != 'Pending PRO':
        return
    self.update_employee_schedule()
    self.create_attendance()

def update_employee_schedule(self):
    existing_schedule = frappe.db.exists('Employee Schedule', {'employee': self.employee, 'date': getdate(self.date_and_time_confirmation), 'roster_type': 'Basic'})
    args = {'employee_availability': 'Medical Appointment', 'operations_role': '', 'shift': '', 'site': '', 'shift_type': '', 'project': '', 'reference_doctype': self.doctype, 'reference_docname': self.name}
    if existing_schedule:
        frappe.db.set_value('Employee Schedule', existing_schedule, args)
    else:
        args.update({'employee': self.employee, 'date': getdate(self.date_and_time_confirmation)})
        frappe.get_doc({'doctype': 'Employee Schedule', **args}).insert(ignore_permissions=True)

def create_attendance(self):
    attendance_doc = frappe.get_doc({'doctype': 'Attendance', 'attendance_date': getdate(self.date_and_time_confirmation), 'employee': self.employee, 'status': 'On Hold', 'comment': _('Created via Medical Appointment: {0}').format(self.name)})
    attendance_doc.insert(ignore_permissions=True)

def validate_payment_invoice_attachment(self):
    if self.workflow_state == 'Completed' and (not self.payment_invoice):
        frappe.throw(_('Payment invoice attachment is required to proceed.'), title=_('Payment Invoice Required'))

def update_attendance_status(self):
    if self.workflow_state not in ['Completed', 'Reschedule Requested']:
        return
    if self.block_roster != 'Yes':
        return
    existing_attendance = frappe.db.exists('Attendance', {'attendance_date': getdate(self.date_and_time_confirmation), 'employee': self.employee, 'status': 'On Hold'})
