    if not purchase_orders:
        return
    po_map = {po['name']: po['one_fm_request_for_purchase'] for po in purchase_orders}
    po_names = list(po_map.keys())
    purchase_order_items = frappe.db.sql('\n        SELECT qty, item_code, parent \n        FROM `tabPurchase Order Item`\n        WHERE parent IN %(po_names)s\n        ', {'po_names': po_names}, as_dict=True)
    if not purchase_order_items:
        return
    update_queries = []
    update_values = []
    for item in purchase_order_items:
        request_for_purchase = po_map.get(item['parent'])
        if request_for_purchase:
            update_queries.append("\n                UPDATE `tabRequest for Purchase Item`\n                SET purchased_quantity = %s\n                WHERE parenttype = 'Request for Purchase'\n                AND parent = %s\n                AND item_code = %s\n                ")
            update_values.append((item['qty'], request_for_purchase, item['item_code']))
    if update_queries:
        for query, values in zip(update_queries, update_values):
            frappe.db.sql(query, values)
    frappe.db.commit()

