def update_shift_assignment_checkin(self) -> None:
    if self.workflow_state == 'Approved' and self.get_doc_before_save().workflow_state != 'Approved':
        if self.assigned_shift:
            if self.log_type == 'IN':
                if self.arrival_time:
                    date_str = frappe.utils.get_date_str(self.date)
                    arrival_time_str = str(self.arrival_time)
                    date_time = datetime.strptime(date_str + ' ' + arrival_time_str, '%Y-%m-%d %H:%M:%S')
                    frappe.db.sql('\n\t\t\t\t\t\t\t\t\t\tUPDATE `tabShift Assignment`\n\t\t\t\t\t\t\t\t\t\tSET start_datetime = %s\n\t\t\t\t\t\t\t\t\t\tWHERE name = %s\n\t\t\t\t\t\t\t\t\t', (date_time, self.assigned_shift))
                    if frappe.db.exists('Employee Checkin', {'shift_assignment': self.assigned_shift, 'log_type': self.log_type}):
                        frappe.db.sql('\n\t\t\t\t\t\t\t\t\t\t\tUPDATE `tabEmployee Checkin`\n\t\t\t\t\t\t\t\t\t\t\tSET shift_actual_start = %s, late_entry = 0\n\t\t\t\t\t\t\t\t\t\t\tWHERE shift_assignment = %s\n\t\t\t\t\t\t\t\t\t\t\tAND log_type = %s\n\t\t\t\t\t\t\t\t\t\t', (date_time, self.assigned_shift, self.log_type))
                    else:
                        create_checkin(self)
            elif self.leaving_time:
                date_time = datetime.strptime(getdate(self.date).strftime('%Y-%m-%d') + ' ' + str(self.leaving_time), '%Y-%m-%d %H:%M:%S')
                frappe.db.sql('\n\t\t\t\t\t\t\t\t\t\tUPDATE `tabShift Assignment`\n\t\t\t\t\t\t\t\t\t\tSET end_datetime = %s\n\t\t\t\t\t\t\t\t\t\tWHERE name = %s\n\t\t\t\t\t\t\t\t\t', (date_time, self.assigned_shift))
                if frappe.db.exists('Employee Checkin', {'shift_assignment': self.assigned_shift, 'log_type': self.log_type}):
                    frappe.db.sql('\n\t\t\t\t\t\t\t\t\t\t\tUPDATE `tabEmployee Checkin`\n\t\t\t\t\t\t\t\t\t\t\tSET shift_actual_end = %s, early_exit = 0\n\t\t\t\t\t\t\t\t\t\t\tWHERE shift_assignment = %s\n\t\t\t\t\t\t\t\t\t\t\tAND log_type = %s\n\t\t\t\t\t\t\t\t\t\t', (date_time, self.assigned_shift, self.log_type))
                else:
                    create_checkin(self)
        frappe.db.commit()

def assign_to_owner(self):
    if not self.get('__unsaved'):
        if self.workflow_state == 'Draft' and self.get_doc_before_save().workflow_state == 'Pending Approver':
            remove(self.doctype, self.name, frappe.session.user, ignore_permissions=False)
            add({'doctype': self.doctype, 'name': self.name, 'assign_to': [self.owner], 'description': _(f'Shift Permission: {self.name} has been returned to Draft. Please check and review.')})
        if self.workflow_state == 'Pending Approver' and self.get_doc_before_save().workflow_state == 'Draft':
            remove(self.doctype, self.name, self.owner, ignore_permissions=False)

