def get_operations_role_list(doctype, txt, searchfield, start, page_len, filters=None):
    from erpnext.controllers.queries import get_fields
    fields = ['name']
    fields = get_fields('Operations Role', fields)
    match_conditions = build_match_conditions('Operations Role')
    match_conditions = 'and {}'.format(match_conditions) if match_conditions else ''
    if filters:
        filter_exist = False
        for filter in filters:
            if filters[filter]:
                filter_exist = True
        if filter_exist:
            filter_conditions = get_filters_cond(doctype, filters, [])
            match_conditions += '{}'.format(filter_conditions)
    return frappe.db.sql("\n\t\tselect %s\n\t\tfrom `tabOperations Role`\n\t\twhere docstatus < 2\n\t\t\tand status = 'Active'\n\t\t\tand (%s like %s or post_name like %s)\n\t\t\t{match_conditions}\n\t\torder by\n\t\t\tcase when name like %s then 0 else 1 end,\n\t\t\tcase when post_name like %s then 0 else 1 end,\n\t\t\tname, post_name limit %s, %s\n\t\t".format(match_conditions=match_conditions) % (', '.join(fields), searchfield, '%s', '%s', '%s', '%s', '%s', '%s'), ('%%%s%%' % txt, '%%%s%%' % txt, '%%%s%%' % txt, '%%%s%%' % txt, start, page_len))

