            if self.price_list:
                dn.selling_price_list = self.price_list
            dn.insert(ignore_permissions=True)
            for i in dn.items:
                i.amount = i.rate * i.qty
            dn.save()
            delivery_note_list.append(dn)
            return {'dn_name_list': [dn.name], 'delivery_note_list': delivery_note_list}
        elif self.create_sales_invoice_as == 'Separate Item Line for Each Site':
            items = []
            for i in dn_items:
                i = frappe._dict(i)
                if i.rate:
                    items.append({'item_code': i.item_code, 'qty': i.qty, 'rate': i.rate, 'amount': i.rate * i.qty, 'site': i.site})
                else:
                    items.append({'item_code': i.item_code, 'qty': i.qty, 'site': i.site})
            dn = frappe.get_doc({'title': self.client + ' - ' + 'Item Line', 'doctype': 'Delivery Note', 'customer': self.client, 'contracts': self.name, 'projects': self.project, 'set_warehouse': 'WRH-1018-0003', 'delivery_based_on': 'Monthly', 'items': items})
            if self.price_list:
                dn.selling_price_list = self.price_list
            dn.insert(ignore_permissions=True)
            for i in dn.items:
                i.amount = i.rate * i.qty
            dn.save()
            delivery_note_list.append(dn)
            return {'dn_name_list': [dn.name], 'delivery_note_list': delivery_note_list}
        elif self.create_sales_invoice_as == 'Separate Invoice for Each Site':
            sites_dict = {}
            for i in dn_items:
                i = frappe._dict(i)
                if sites_dict.get(i.site):
                    sites_dict.get(i.site).append(i)
                else:
                    sites_dict[i.site] = [i]
            for site, _items in sites_dict.items():
                items = []
                for i in _items:
                    if i.rate:
                        items.append({'item_code': i.item_code, 'qty': i.qty, 'rate': i.rate, 'amount': i.rate * i.qty, 'site': site})
