                        items.append({'item_code': i.item_code, 'qty': i.qty, 'site': i.site})
                dn = frappe.get_doc({'title': self.client + ' - ' + site, 'doctype': 'Delivery Note', 'customer': self.client, 'contracts': self.name, 'projects': self.project, 'set_warehouse': 'WRH-1018-0003', 'delivery_based_on': 'Monthly', 'items': items})
                if self.price_list:
                    dn.selling_price_list = self.price_list
                dn.insert(ignore_permissions=True)
                for i in dn.items:
                    i.amount = i.rate * i.qty
                dn.save()
                delivery_note_list.append(dn)
            return {'dn_name_list': [dn.name for dn in delivery_note_list], 'delivery_note_list': delivery_note_list}
