@frappe.whitelist()
def changes_action(action, parent, ids):
    ids = [id for id in ids.rstrip(',').split(',')]
    ids = ', '.join(['"{}"'.format(value) for value in ids])
    if action == 'Approved':
        cleanup_logs(parent, ids)
    elif action == 'Rejected':
        log = frappe.db.sql('\n\t\t\tselect diff from `tabOperations Changes` where name in ({ids})\n\t\t'.format(ids=ids), as_dict=1)
        for change in log:
            change = json.loads(frappe._dict(change).diff)
            revert_changes(change, 'Operations Site', parent)
        cleanup_logs(parent, ids)
    return True

def revert_changes(change, doctype, docname):
    cond = ', '.join(['{fieldname}="{old_value}"'.format(fieldname=field[0], old_value=field[1]) for field in change])
    if cond:
        frappe.db.sql('\n\t\t\tUPDATE `tab{doctype}` SET {cond} WHERE name="{docname}"\n\t\t'.format(doctype=doctype, cond=cond, docname=docname))
        frappe.db.commit()
    return True

def cleanup_logs(parent, ids):
    if parent and ids:
        frappe.db.sql('\n\t\t\tdelete from `tabOperations Changes` where parenttype="Operations Site" and parent="{parent}" and name in ({ids})\n\t\t'.format(parent=parent, ids=ids))
        frappe.db.commit()

