def search_article(text=None, page=None):
    if not text:
        return {}
    pagination = paginate(text, page)
    return pagination

def paginate(text, page=0, paginate_by=5):
    prev, next, search = (0, 0, False)
    query = f'\n        SELECT name, title, content, creation, category, subcategory, route\n        FROM `tabHelp Article`\n        WHERE published=1 AND title LIKE "%{text}%" OR content LIKE "%{text}%"\n        GROUP BY title\n    '
    if page:
        page = int(page)
        results = frappe.db.sql(query + f'LIMIT {page * paginate_by - paginate_by}, {paginate_by};', as_dict=True)
        next_set = frappe.db.sql(query + f'LIMIT {page * paginate_by}, {paginate_by};', as_dict=True)
        if next_set:
            prev, next = (page - 1, page + 1)
        else:
            prev, next = (page - 1, 0)
    else:
        count = frappe.db.sql(f'\n            SELECT COUNT(name) as count, title, content, creation FROM `tabHelp Article`\n            WHERE published=1 AND title LIKE "%{text}%" OR content LIKE "%{text}%"\n            ', as_dict=True)[0].count
        if count > paginate_by:
            prev, next = (0, 2)
        results = frappe.db.sql(f'{query} LIMIT {paginate_by};', as_dict=True)
    if text:
        search = True
    for i in results:
        i.creation = i.creation.date()
        i.content = remove_html_tags(i.content)[:200] + '...'
        if text in i.content:
            i.content = i.content.replace(text, f'<i class="text-warning">{text}</i>')
        if text in i.title:
            i.title = i.title.replace(text, f'<i class="text-warning">{text}</i>')
    return frappe._dict({'results': results, 'prev': prev, 'next': next, 'search': search, 'q': text})

