def get_data(filters):
    filters = filters or {}
    conditions = ['rfp.docstatus = 1']
    params = {}
    if filters.get('from_date'):
        conditions.append('DATE(rfp.creation) >= %(from_date)s')
        params['from_date'] = filters.get('from_date')
    if filters.get('to_date'):
        conditions.append('DATE(rfp.creation) <= %(to_date)s')
        params['to_date'] = filters.get('to_date')
    if filters.get('rfp_no'):
        conditions.append('rfp.name = %(rfp_no)s')
        params['rfp_no'] = filters.get('rfp_no')
    if filters.get('rfp_type'):
        conditions.append('rfp.type = %(rfp_type)s')
        params['rfp_type'] = filters.get('rfp_type')
    if filters.get('project'):
        conditions.append('rfp.project = %(project)s')
        params['project'] = filters.get('project')
    if filters.get('site'):
        conditions.append('rfm.site = %(site)s')
        params['site'] = filters.get('site')
    if filters.get('employee_id'):
        conditions.append('rfp.employee = %(employee_id)s')
        params['employee_id'] = filters.get('employee_id')
    if filters.get('department'):
        conditions.append('rfp.department = %(department)s')
        params['department'] = filters.get('department')
    if filters.get('erf_no'):
        conditions.append('rfm.erf = %(erf_no)s')
        params['erf_no'] = filters.get('erf_no')
    where_clause = ' AND '.join(conditions) if conditions else '1=1'
    rows = frappe.db.sql(f'\n        SELECT\n            rfp.name AS rfp_no,\n            DATE(rfp.creation) AS rfp_date,\n            rfp.type AS type,\n            rfp.currency,\n            rfp.employee AS employee_id,\n            rfp.employee_name AS employee_name,\n            rfp.department AS department,\n            rfp.project AS project,\n            rfm.site AS operation_site,\n            rfm.erf AS erf_no,\n            item.item_code AS item_code,\n            item.qty AS qty,\n            item.uom AS uom,\n            item.supplier AS supplier,\n            (item.rate * item.qty) AS rfp_amount,\n            item.base_amount AS rfp_amount_company_currency\n        FROM `tabRequest for Purchase` rfp\n        INNER JOIN `tabRequest for Purchase Quotation Item` item ON item.parent = rfp.name\n        LEFT JOIN `tabRequest for Material` rfm ON rfm.name = rfp.request_for_material\n        WHERE {where_clause}\n          AND item.item_code IS NOT NULL\n        ORDER BY rfp.creation ASC\n        ', params, as_dict=True)
    if not rows:
        return []
    rfp_nos = {r['rfp_no'] for r in rows}
    po_rows = frappe.db.sql('\n        SELECT po.name AS po_name, poi.item_code, po.one_fm_request_for_purchase AS rfp_no\n        FROM `tabPurchase Order` po\n        INNER JOIN `tabPurchase Order Item` poi ON poi.parent = po.name\n        WHERE po.docstatus IN (0,1)\n          AND po.one_fm_request_for_purchase IN (%s)\n        ' % ','.join(['%s'] * len(rfp_nos)), tuple(rfp_nos), as_dict=True)
    po_map = {}
    for pr in po_rows:
        if not pr.get('item_code'):
            continue
        key = (pr['rfp_no'], pr['item_code'])
        po_map.setdefault(key, set()).add(pr['po_name'])
    for r in rows:
        key = (r['rfp_no'], r['item_code'])
        r['purchase_order'] = ', '.join(sorted(po_map.get(key, []))) if po_map.get(key) else ''
    return rows

