def execute(filters=None):
    is_reposting_item_valuation_in_progress()
    if not filters:
        filters = {}
    from_date = filters.get('from_date')
    to_date = filters.get('to_date')
    if filters.get('company'):
        company_currency = erpnext.get_company_currency(filters.get('company'))
    else:
        company_currency = frappe.db.get_single_value('Global Defaults', 'default_currency')
    include_uom = filters.get('include_uom')
    columns = get_columns(filters)
    items = get_items(filters)
    sle = get_stock_ledger_entries(filters, items)
    if filters.get('show_stock_ageing_data'):
        filters['show_warehouse_wise_stock'] = True
        item_wise_fifo_queue = get_fifo_queue(filters, sle)
    if not sle:
        return (columns, [])
    iwb_map = get_item_warehouse_map(filters, sle)
    item_map = get_item_details(items, sle, filters)
    item_reorder_detail_map = get_item_reorder_details(item_map.keys())
    data = []
    conversion_factors = {}
    _func = itemgetter(1)
    for company, item, warehouse in sorted(iwb_map):
        if item_map.get(item):
            qty_dict = iwb_map[company, item, warehouse]
            item_reorder_level = 0
            item_reorder_qty = 0
            if item + warehouse in item_reorder_detail_map:
                item_reorder_level = item_reorder_detail_map[item + warehouse]['warehouse_reorder_level']
                item_reorder_qty = item_reorder_detail_map[item + warehouse]['warehouse_reorder_qty']
            report_data = {'currency': company_currency, 'item_code': item, 'warehouse': warehouse, 'company': company, 'reorder_level': item_reorder_level, 'reorder_qty': item_reorder_qty}
            report_data.update(item_map[item])
            report_data.update(qty_dict)
            if include_uom:
                conversion_factors.setdefault(item, item_map[item].conversion_factor)
            if filters.get('show_stock_ageing_data'):
                fifo_queue = item_wise_fifo_queue[item, warehouse].get('fifo_queue')
                stock_ageing_data = {'average_age': 0, 'earliest_age': 0, 'latest_age': 0}
                if fifo_queue:
                    fifo_queue = sorted(filter(_func, fifo_queue), key=_func)
                    if not fifo_queue:
                        continue
                    stock_ageing_data['average_age'] = get_average_age(fifo_queue, to_date)
                    stock_ageing_data['earliest_age'] = date_diff(to_date, fifo_queue[0][1])
                    stock_ageing_data['latest_age'] = date_diff(to_date, fifo_queue[-1][1])
                report_data.update(stock_ageing_data)
            data.append(report_data)
    item_reservation_dict = {}
    reservations = frappe.db.sql(f"\n\tSELECT item_code, sum(qty) as qty FROM `tabItem Reservation`\n\tWHERE docstatus=1 AND status in ('Active', 'Completed')\n\tAND ((from_date BETWEEN '{from_date}' AND '{to_date}') OR\n\t(to_date BETWEEN '{from_date}' AND '{to_date}'))\n\tGROUP BY item_code\n\t;", as_dict=1)
    added_items = []
    new_report_data_list = []
    new_report_data_dict = {}
    for i in reservations:
        new_report_data_dict[i.item_code] = i.qty
    for i in data:
        if not i.get('item_code') in added_items:
            if new_report_data_dict.get(i.get('item_code')):
                i['reserved_qty'] = new_report_data_dict.get(i.get('item_code'))
                added_items.append(i.get('item_code'))
                new_report_data_list.append(i)
            else:
                new_report_data_list.append(i)
        else:
            new_report_data_list.append(i)
    data = new_report_data_list
    add_additional_uom_columns(columns, data, include_uom, conversion_factors)
    return (columns, data)

