def get_item_warehouse_map(filters, sle):
    iwb_map = {}
    from_date = getdate(filters.get('from_date'))
    to_date = getdate(filters.get('to_date'))
    float_precision = cint(frappe.db.get_default('float_precision')) or 3
    for d in sle:
        key = (d.company, d.item_code, d.warehouse)
        if key not in iwb_map:
            iwb_map[key] = frappe._dict({'opening_qty': 0.0, 'opening_val': 0.0, 'in_qty': 0.0, 'in_val': 0.0, 'out_qty': 0.0, 'out_val': 0.0, 'bal_qty': 0.0, 'bal_val': 0.0, 'val_rate': 0.0})
        qty_dict = iwb_map[d.company, d.item_code, d.warehouse]
        if d.voucher_type == 'Stock Reconciliation' and (not d.batch_no):
            qty_diff = flt(d.qty_after_transaction) - flt(qty_dict.bal_qty)
        else:
            qty_diff = flt(d.actual_qty)
        value_diff = flt(d.stock_value_difference)
        if d.posting_date < from_date or (d.posting_date == from_date and d.voucher_type == 'Stock Reconciliation' and (frappe.db.get_value('Stock Reconciliation', d.voucher_no, 'purpose') == 'Opening Stock')):
            qty_dict.opening_qty += qty_diff
            qty_dict.opening_val += value_diff
        elif d.posting_date >= from_date and d.posting_date <= to_date:
            if flt(qty_diff, float_precision) >= 0:
                qty_dict.in_qty += qty_diff
                qty_dict.in_val += value_diff
            else:
                qty_dict.out_qty += abs(qty_diff)
                qty_dict.out_val += abs(value_diff)
        qty_dict.val_rate = d.valuation_rate
        qty_dict.bal_qty += qty_diff
        qty_dict.bal_val += value_diff
    iwb_map = filter_items_with_no_transactions(iwb_map, float_precision)
    return iwb_map

def filter_items_with_no_transactions(iwb_map, float_precision):
    for company, item, warehouse in sorted(iwb_map):
        qty_dict = iwb_map[company, item, warehouse]
        no_transactions = True
        for key, val in iteritems(qty_dict):
            val = flt(val, float_precision)
            qty_dict[key] = val
            if key != 'val_rate' and val:
                no_transactions = False
        if no_transactions:
            iwb_map.pop((company, item, warehouse))
    return iwb_map

