def get_item_details(items, sle, filters):
    item_details = {}
    if not items:
        items = list(set((d.item_code for d in sle)))
    if not items:
        return item_details
    cf_field = cf_join = ''
    if filters.get('include_uom'):
        cf_field = ', ucd.conversion_factor'
        cf_join = 'left join `tabUOM Conversion Detail` ucd on ucd.parent=item.name and ucd.uom=%s' % frappe.db.escape(filters.get('include_uom'))
    res = frappe.db.sql('\n\t\tselect\n\t\t\titem.name, item.item_name, item.description, item.item_group, item.brand, item.stock_uom %s\n\t\tfrom\n\t\t\t`tabItem` item\n\t\t\t%s\n\t\twhere\n\t\t\titem.name in (%s)\n\t' % (cf_field, cf_join, ','.join(['%s'] * len(items))), items, as_dict=1)
    for item in res:
        item_details.setdefault(item.name, item)
    if filters.get('show_variant_attributes', 0) == 1:
        variant_values = get_variant_values_for(list(item_details))
        item_details = {k: v.update(variant_values.get(k, {})) for k, v in iteritems(item_details)}
    return item_details

def get_item_reorder_details(items):
    item_reorder_details = frappe._dict()
