def validate(self):
    self.check_date()
    self.check_qty()

def check_date(self):
    if self.from_date < today() or self.to_date < today():
        frappe.throw(_('You cannot backdate reservation date.'))

def check_qty(self):
    if self.qty <= 0:
        frappe.throw(_('You cannot reserve 0 or less item.'))

def check_balance(self):
    item_balance = get_item_balance(self.item_code).get('total', 0)
    if item_balance < self.qty:
        frappe.throw(_(f'\n\t\t\t\t\tReservation QTY <b>{self.qty}</b> is greater than available QTY <b>{item_balance}</b>\n\t\t\t\t\t<br>for item <b>{self.item_code}</b>.\n\t\t\t\t'))

@frappe.whitelist()
def close_reservation(self):
    self.db_set('status', 'Completed')
    return True

@frappe.whitelist()
def update_reservation(self, qty, field, type):
    print(qty, field, type, '\n', self.get(field))
    if type == 'reduce' and field == 'qty':
        self.db_set(field, self.get(field) - qty)
    elif type == 'increase' and field == 'qty':
        self.db_set(field, self.get(field) + qty)
    elif type == 'issue' and field == 'issued_qty':
        self.db_set(field, self.get(field) - qty)
    self.reload()
    if self.issued_qty == self.qty:
        self.db_set('status', 'Completed')
    self.reload()
    return True

@frappe.whitelist()
def update_issue(self, qty, field, type):
    print(qty, field, type, self.get('issued_qty'), '\n')
    if type == 'reduce' and field == 'issued_qty':
        if qty >= self.qty or qty <= 0 or qty - self.issued_qty > self.issued_qty:
            frappe.throw(_('\n\t\t\t\t\tQTY to be reduced cannot be greater than reserved QTY nor <br>\n\t\t\t\t\tgreater than issued QTY.\n\t\t\t\t'))
        else:
            self.db_set(field, self.get('issued_qty') - qty)
    elif type == 'increase' and field == 'issued_qty':
        if self.qty < qty or qty + self.issued_qty > self.qty:
            frappe.throw(_(f'\n\t\t\t\t\tQTY to be issued <b>{qty}</b> must be less or equal to\n\t\t\t\t\treserved QTY <b>{self.qty}</> or your value may have exceed issued QTY.\n\t\t\t\t'))
        else:
            self.db_set(field, self.get('issued_qty') + qty)
    self.reload()
    if self.issued_qty == self.qty:
        self.db_set('status', 'Completed')
        frappe.msgprint(f'\n\t\t\t\tThis reservation has be closed.\n\t\t\t')
    self.reload()
    return True

methods.signature:
def validate(self):
    self.check_date()
    self.check_qty()

def check_date(self):
    if self.from_date < today() or self.to_date < today():
        frappe.throw(_('You cannot backdate reservation date.'))

def check_qty(self):
    if self.qty <= 0:
        frappe.throw(_('You cannot reserve 0 or less item.'))

def check_balance(self):
    item_balance = get_item_balance(self.item_code).get('total', 0)
    if item_balance < self.qty:
        frappe.throw(_(f'\n\t\t\t\t\tReservation QTY <b>{self.qty}</b> is greater than available QTY <b>{item_balance}</b>\n\t\t\t\t\t<br>for item <b>{self.item_code}</b>.\n\t\t\t\t'))

@frappe.whitelist()
def close_reservation(self):
    self.db_set('status', 'Completed')
    return True

@frappe.whitelist()
def update_reservation(self, qty, field, type):
    print(qty, field, type, '\n', self.get(field))
    if type == 'reduce' and field == 'qty':
        self.db_set(field, self.get(field) - qty)
    elif type == 'increase' and field == 'qty':
        self.db_set(field, self.get(field) + qty)
    elif type == 'issue' and field == 'issued_qty':
        self.db_set(field, self.get(field) - qty)
    self.reload()
    if self.issued_qty == self.qty:
        self.db_set('status', 'Completed')
    self.reload()
    return True

@frappe.whitelist()
def update_issue(self, qty, field, type):
    print(qty, field, type, self.get('issued_qty'), '\n')
    if type == 'reduce' and field == 'issued_qty':
        if qty >= self.qty or qty <= 0 or qty - self.issued_qty > self.issued_qty:
            frappe.throw(_('\n\t\t\t\t\tQTY to be reduced cannot be greater than reserved QTY nor <br>\n\t\t\t\t\tgreater than issued QTY.\n\t\t\t\t'))
        else:
            self.db_set(field, self.get('issued_qty') - qty)
    elif type == 'increase' and field == 'issued_qty':
        if self.qty < qty or qty + self.issued_qty > self.qty:
            frappe.throw(_(f'\n\t\t\t\t\tQTY to be issued <b>{qty}</b> must be less or equal to\n\t\t\t\t\treserved QTY <b>{self.qty}</> or your value may have exceed issued QTY.\n\t\t\t\t'))
        else:
            self.db_set(field, self.get('issued_qty') + qty)
    self.reload()
    if self.issued_qty == self.qty:
        self.db_set('status', 'Completed')
        frappe.msgprint(f'\n\t\t\t\tThis reservation has be closed.\n\t\t\t')
    self.reload()
    return True

