def check_related_pos_before_cancel(doc):
    doc_dict = json.loads(doc)
    approved_pos = frappe.db.get_list('Purchase Order', {'one_fm_request_for_purchase': doc_dict.get('name'), 'docstatus': 1, 'workflow_state': 'Approved'}, ['name'])
    draft_pos = frappe.db.get_list('Purchase Order', {'one_fm_request_for_purchase': doc_dict.get('name'), 'docstatus': ['in', [0, 1]], 'workflow_state': 'Draft'}, ['name'])
    pending_pos = frappe.db.get_list('Purchase Order', {'one_fm_request_for_purchase': doc_dict.get('name'), 'docstatus': ['in', [0, 1]], 'workflow_state': ['in', ['Pending Purchase Manager', 'Pending Finance Approver']]}, ['name', 'workflow_state'])
    if approved_pos:
        all_other_pos = draft_pos + pending_pos
        if all_other_pos:
            approved_list = ', '.join([po.name for po in approved_pos])
            other_list = ', '.join([po.name for po in all_other_pos])
            return {'error': True, 'type': 'mixed', 'title': 'Cancellation Blocked – Mixed Purchase Order Stages Found', 'message': f"Please note that {doc_dict.get('name')} has related Purchase Orders in different stages: {other_list} > Pending Approval, {approved_list} > Approved. Cancellation of this RFP is not allowed while Approved POs exist. You must first cancel the Approved POs.", 'approved_list': approved_list, 'other_list': other_list}
        else:
            po_list = ', '.join([po.name for po in approved_pos])
            return {'error': True, 'type': 'approved_only', 'title': 'RFP Cancellation blocked. Approved Purchase Order found.', 'message': f"Please note that {doc_dict.get('name')} has related Purchase Orders ({po_list}) in Approved stage. To proceed, you must first cancel these Purchase Orders. Cancellation of this RFP is not allowed until all related POs are cancelled.", 'approved_list': po_list}
    elif draft_pos and pending_pos:
        all_draft_pending = draft_pos + pending_pos
        po_list = ', '.join([po.name for po in all_draft_pending])
        return {'error': True, 'type': 'draft_pending_confirmation', 'title': 'Purchase Order is in Pending Approval Stage', 'message': f"Please note that {doc_dict.get('name')} has related Purchase Orders ({po_list}) currently in Pending Approval stage. Cancelling this RFP will automatically delete these Purchase Orders. Do you want to proceed?", 'draft_pending_list': po_list}
    elif draft_pos:
        po_list = ', '.join([po.name for po in draft_pos])
        return {'error': True, 'type': 'draft_confirmation', 'title': 'Purchase Order is in Pending Approval Stage', 'message': f"Please note that {doc_dict.get('name')} has related Purchase Orders ({po_list}) currently in Pending Approval stage. Cancelling this RFP will automatically delete these Purchase Orders. Do you want to proceed?", 'draft_list': po_list}
    return {'error': False}

