        wh = warehouse if warehouse else self.warehouse
        supplier_groups = {}
        for item in self.items_to_order:
            if item.supplier not in supplier_groups:
                supplier_groups[item.supplier] = []
            supplier_groups[item.supplier].append({'item_code': item.item_code, 'qty': item.qty, 'rate': item.rate, 'delivery_date': item.delivery_date, 'uom': item.uom, 'stock_uom': item.stock_uom, 'conversion_factor': item.conversion_factor or 1, 'stock_qty': item.stock_qty, 'stock_rate': item.stock_rate, 'description': item.description, 'warehouse': item.t_warehouse if item.t_warehouse else wh, 'quotation': item.quotation, 'item_name': getattr(item, 'item_name', None), 'is_refundable': getattr(item, 'is_refundable', 0), 'margin_known': getattr(item, 'margin_known', ''), 'margin_type': getattr(item, 'margin_type', ''), 'margin_rate_or_amount': getattr(item, 'margin_rate_or_amount', 0)})
        for supplier, items_list in supplier_groups.items():
            po = create_purchase_order(supplier=supplier, request_for_purchase=self.name, warehouse=wh, items_list=items_list, rfp_doc=self.as_dict(), do_not_submit=True)
