def automatic_checkout():
    now_time = now_datetime().strftime('%Y-%m-%d %H:%M')
    shifts_list = get_active_shifts(now_time)
    for shift in shifts_list:
        if strfdelta(shift.end_time, '%H:%M:%S') == cstr((get_datetime(now_time) - timedelta(minutes=cint(shift.allow_check_out_after_shift_end_time))).time()):
            date = getdate() if shift.start_time < shift.end_time else getdate() - timedelta(days=1)
            recipients = frappe.db.sql('\n\t\t\t\tSELECT DISTINCT emp.name FROM `tabShift Assignment` tSA, `tabEmployee` emp\n\t\t\t\tWHERE\n\t\t\t\t\ttSA.employee = emp.name\n\t\t\t\tAND tSA.start_date=\'{date}\'\n\t\t\t\tAND tSA.shift_type=\'{shift_type}\'\n\t\t\t\tAND tSA.docstatus=1\n\t\t\t\tAND tSA.employee\n\t\t\t\tNOT IN(SELECT employee FROM `tabEmployee Checkin` empChkin\n\t\t\t\tWHERE\n\t\t\t\t\tempChkin.log_type="OUT"\n\t\t\t\tAND empChkin.skip_auto_attendance=0\n\t\t\t\tAND date(empChkin.time)=\'{date}\'\n\t\t\t\tAND empChkin.shift_type=\'{shift_type}\')\n\t\t\t'.format(date=cstr(date), shift_type=shift.name), as_list=1)
            if len(recipients) > 0:
                recipients = [recipient[0] for recipient in recipients if recipient[0]]
                for recipient in recipients:
                    checkin = frappe.new_doc('Employee Checkin')
                    checkin.employee = recipient
                    checkin.log_type = 'OUT'
                    checkin.skip_auto_attendance = 0
                    checkin.save()
            frappe.db.commit()

