        shift_types_dict = {}
        for i in shift_types:
            i.start_datetime = f'{date} {(datetime.min + i.start_time).time()}'
            if i.end_time.total_seconds() < i.start_time.total_seconds():
                i.end_datetime = f'{add_days(date, 1)} {(datetime.min + i.end_time).time()}'
            else:
                i.end_datetime = f'{date} {(datetime.min + i.end_time).time()}'
            shift_types_dict[i.name] = i
        default_shift = frappe.get_doc('Shift Type', '"Standard|Morning|08:00:00-17:00:00|9 hours"').as_dict()
        existing_shift = frappe.db.get_list('Shift Assignment', filters={'start_date': date, 'shift_type': ['IN', shift_type], 'docstatus': 1, 'roster_type': ['IN', ['Basic']], 'status': 'Active'}, fields=['employee'])
        existing_shift_list = [i.employee for i in existing_shift]
        shift_request = frappe.db.get_list('Shift Request', filters={'employee': ['IN', [i.employee for i in roster]], 'from_date': ['<=', date], 'to_date': ['>=', date], 'roster_type': 'Basic', 'workflow_state': 'Approved'}, fields=['*'])
        shift_request_dict = {}
        for i in shift_request:
            shift_request_dict[i.employee] = i
        sites = []
        for i in roster:
            if not i.site in sites:
                sites.append(i.site)
        sites_list = frappe.db.get_list('Operations Site', filters={'name': ['IN', sites]}, fields=['name', 'site_location'])
        sites_list_dict = {}
        for i in sites_list:
            sites_list_dict[i.name] = i.site_location
        todays_leaves = get_today_leaves(str(date))
        employees_on_vacation = [i.name for i in frappe.db.get_list('Employee', {'status': 'Vacation'})]
        for i in employees_on_vacation:
            if not i in todays_leaves:
                todays_leaves.append(i)
        roster = [i for i in roster if not i.employee in todays_leaves]
        if roster:
            query_head = '\n\t\t\t\tINSERT INTO `tabShift Assignment` (`name`, `company`, `docstatus`, `employee`, `employee_name`, `shift_type`, `site`, `project`, `status`,\n\t\t\t\t`shift_classification`, `site_location`, `start_date`, `start_datetime`, `end_datetime`, `department`,\n\t\t\t\t`shift`, `operations_role`, `post_abbrv`, `roster_type`, `owner`, `modified_by`, `creation`, `modified`,\n\t\t\t\t`shift_request`, `check_in_site`, `check_out_site`,`custom_day_off_ot`, `employee_schedule`, `custom_on_the_job_training`)\n\t\t\t\tVALUES\n\t\t\t'
            query_body = ''
            has_rostered = []
            for r in roster:
                _day_off_ot = 0
                if not r.employee in existing_shift_list:
                    if shift_request_dict.get(r.employee):
                        _shift_request = shift_request_dict.get(r.employee)
                        _shift_type = shift_types_dict.get(_shift_request.shift_type) or default_shift
                        _project_r = frappe.db.get_value('Operations Shift', {'name': _shift_request.operations_shift}, ['project'])
                        shift_r_start_time = date + ' ' + str(_shift_type.start_time)
                        _day_off_ot = 1 if shift_request_dict.get(r.employee).get('purpose') == 'Day Off Overtime' else 0
                        if _shift_type.start_time > _shift_type.end_time:
                            shift_r_end_time = str(add_to_date(date, days=1)) + ' ' + str(_shift_type.end_time)
                        else:
                            shift_r_end_time = str(date) + ' ' + str(_shift_type.end_time)
                        query_body += f'''\n\t\t\t\t\t\t(\n\t\t\t\t\t\t\t"HR-SHA-{date}-{r.employee}", "{frappe.defaults.get_user_default('company')}", 1, "{r.employee}", "{r.employee_name}", '{_shift_request.shift_type}',\n\t\t\t\t\t\t\t"{_shift_request.site or ''}", "{_project_r or ''}", 'Active', '{_shift_request.shift_type}', "{sites_list_dict.get(_shift_request.site) or ''}", "{date}",\n\t\t\t\t\t\t\t"{shift_r_start_time or str(date) + ' 08:00:00'}", "{shift_r_end_time or str(date) + ' 17:00:00'}", "{r.department}",\n\t\t\t\t\t\t\t"{_shift_request.operations_shift or ''}", "{_shift_request.operations_role or ''}", "{r.post_abbrv or ''}", "{_shift_request.roster_type}",\n\t\t\t\t\t\t\t"{owner}", "{owner}", "{creation}", "{creation}", "{_shift_request.name}", "{_shift_request.check_in_site}", "{_shift_request.check_out_site}","{_day_off_ot}", "{r.name}", "{(r.on_the_job_training if r.employee_availability == 'On-the-job Training' else '')}"),'''
