def get_employee_shift(employee_id, date_type='month'):
    """
		Fetch employee information relating to
		leave_balance, shift, penalties and attendance
	"""
    today = datetime.today()
    _start = today.replace(day=1).date()
    _end = today.replace(day=calendar.monthrange(today.year, today.month)[1]).date()
    if date_type == 'year':
        _start = date(today.year, 1, 31)
        _end = date(today.year, 12, 31)
    penalty_start_date = datetime.now() - timedelta(days=364)
    penalty_end_date = date(today.year, today.month, today.day)
    data = {'leave_balance': '', 'penalties': '', 'days_worked': '', 'shift_time_from': '', 'shift_time_to': '', 'shift_location': '', 'shift_latitude_and_longitude': ''}
    try:
        employee = frappe.get_doc('Employee', employee_id)
        shift_assignment = frappe.db.get_list('Shift Assignment', filters=[['employee', '=', employee.name]], fields=['name', 'employee', 'site', 'shift_type'], order_by='modified desc', limit=1)
        if len(shift_assignment):
            site = frappe.get_doc('Operations Site', shift_assignment[0].site)
            shift_location = frappe.get_doc('Location', site.site_location)
            shift_type = frappe.get_doc('Shift Type', shift_assignment[0].shift_type)
            days_worked = frappe.db.get_list('Attendance', filters=[['employee', '=', employee.name], ['status', '=', 'Present'], ['attendance_date', 'BETWEEN', [_start, _end]]], fields=['COUNT(*) as count', 'name', 'employee', 'status', 'attendance_date'], order_by='modified desc')[0].count
            penalties = frappe.db.sql(f'''\n\t\t\t\tSELECT COUNT(*) as count\n\t\t\t\tFROM `tabPenalty` p\n\t\t\t\tWHERE p.recipient_employee="{employee.name}"\n\t\t\t\tAND p.workflow_state = 'Penalty Accepted'\n\t\t\t\tAND p.penalty_issuance_time BETWEEN "{penalty_start_date} 00:00:00" AND "{penalty_end_date} 23:59:59";\n\t\t\t''', as_dict=1)[0].count
            filters = frappe._dict({'from_date': _start, 'to_date': _end, 'employee': employee.name})
            leave_balance = sum([i.closing_balance for i in get_leave_balance(filters)])
            return {'message': f'Employee shift record retrieved from {_start} to {_end}', 'data': {'employee': employee.name, 'leave_balance': leave_balance, 'penalties': penalties, 'days_worked': days_worked, 'shift_time_from': shift_type.start_time, 'shift_time_to': shift_type.end_time, 'shift_location': shift_location.name, 'shift_latitude_and_longitude': {'latitude': shift_location.latitude, 'longitude': shift_location.longitude}}, 'status': 201, 'success': True}
        else:
            return {'message': f'No shift found for {employee.name}', 'data': {}, 'status': 201, 'success': False}
    except Exception as e:
        return {'message': str(e), 'data': {}, 'status': 404, 'success': False}

