	returns
	status of the OTP entered 
	"""
    try:
        login_manager = frappe.local.login_manager
        check_otp = confirm_otp_token(login_manager, otp, temp_id)
        password_token = frappe.db.get_value('Password Reset Token', {'temp_id': temp_id}, ['name', 'status', 'expiration_time'], as_dict=1)
