def validate_expense_against_budget(args):
    args = frappe._dict(args)
    if args.get('company') and (not args.fiscal_year):
        args.fiscal_year = get_fiscal_year(args.get('posting_date'), company=args.get('company'))[0]
        frappe.flags.exception_approver_role = frappe.get_cached_value('Company', args.get('company'), 'exception_budget_approver_role')
    if not args.account:
        args.account = args.get('expense_account')
    if not (args.get('account') and args.get('cost_center')) and args.item_code:
        args.cost_center, args.account = get_item_details(args)
    if not args.account:
        return
    for budget_against in ['project', 'cost_center'] + get_accounting_dimensions():
        if args.get(budget_against) and args.account and frappe.db.get_value('Account', {'name': args.account, 'root_type': 'Expense'}):
            doctype = frappe.unscrub(budget_against)
            if frappe.get_cached_value('DocType', doctype, 'is_tree'):
                lft, rgt = frappe.db.get_value(doctype, args.get(budget_against), ['lft', 'rgt'])
                condition = 'and exists(select name from `tab%s`\n\t\t\t\t\twhere lft<=%s and rgt>=%s and name=b.%s)' % (doctype, lft, rgt, budget_against)
                args.is_tree = True
            else:
                condition = 'and b.%s=%s' % (budget_against, frappe.db.escape(args.get(budget_against)))
                args.is_tree = False
            args.budget_against_field = budget_against
            args.budget_against_doctype = doctype
            budget_records = frappe.db.sql('\n\t\t\t\tselect\n\t\t\t\t\tb.{budget_against_field} as budget_against, ba.budget_amount, b.monthly_distribution,\n\t\t\t\t\tifnull(b.applicable_on_stock_entry, 0) as for_stock_entry,\n\t\t\t\t\tb.action_if_annual_budget_exceeded_on_se, b.action_if_accumulated_monthly_budget_exceeded_on_se\n\t\t\t\tfrom\n\t\t\t\t\t`tabBudget` b, `tabBudget Account` ba\n\t\t\t\twhere\n\t\t\t\t\tb.name=ba.parent and b.fiscal_year=%s\n\t\t\t\t\tand ba.account=%s and b.docstatus=1\n\t\t\t\t\t{condition}\n\t\t\t'.format(condition=condition, budget_against_field=budget_against), (args.fiscal_year, args.account), as_dict=True)
            if budget_records:
                validate_budget_records(args, budget_records)

def validate_budget_records(args, budget_records):
    for budget in budget_records:
        if flt(budget.budget_amount):
            amount = get_amount(args, budget)
            yearly_action = budget.action_if_annual_budget_exceeded_on_se
            monthly_action = budget.action_if_accumulated_monthly_budget_exceeded_on_se
            if monthly_action in ['Stop', 'Warn']:
                budget_amount = get_accumulated_monthly_budget(budget.monthly_distribution, args.posting_date, args.fiscal_year, budget.budget_amount)
                args['month_end_date'] = get_last_day(args.posting_date)
                compare_expense_with_budget(args, budget_amount, _('Accumulated Monthly'), monthly_action, budget.budget_against, amount)
            if yearly_action in ('Stop', 'Warn') and monthly_action != 'Stop' and (yearly_action != monthly_action):
                compare_expense_with_budget(args, flt(budget.budget_amount), _('Annual'), yearly_action, budget.budget_against, amount)

