def revoke_token(access_token):
    url = f'{get_url()}/api/method/frappe.integrations.oauth2.revoke_token'
    headers = {'Content-Type': 'application/x-www-form-urlencoded'}
    data = {'token': access_token}
    try:
        response = requests.post(url, headers=headers, data=data)
        response.raise_for_status()
        return True
    except requests.exceptions.RequestException as e:
        print(f'Error revoking token: {e}')
        return False

def get_working_days_details(self, joining_date=None, relieving_date=None, lwp=None, for_preview=0):
    payroll_based_on = frappe.db.get_value('Payroll Settings', None, 'payroll_based_on')
    include_holidays_in_total_working_days = frappe.db.get_single_value('Payroll Settings', 'include_holidays_in_total_working_days')
    if not (joining_date and relieving_date):
        joining_date, relieving_date = self.get_joining_and_relieving_dates()
    start_date = getdate(self.start_date) if getdate(joining_date) < getdate(self.start_date) else getdate(joining_date)
    end_date = getdate(self.end_date) if getdate(relieving_date) < getdate(self.end_date) else getdate(relieving_date)
    if self.payroll_type == 'Basic':
        working_days = date_diff(end_date, start_date) + 1
    else:
        working_days = get_ot_days(self.employee, start_date, end_date)
    if for_preview:
        self.total_working_days = working_days
        self.payment_days = working_days
        return
    holidays = self.get_holidays_for_employee(start_date, end_date)
    '\n    working_days_list is the list of date starts from start_date to end date if the payroll_type is Basic\n    For Over Time it will not be sequance of date starts from start date to end date.\n    Example:\n        start_date = "01/01/2023", end_date = "30/01/2023"\n        Basic:\n            working_days_list is "01/01/2023", "02/01/2023", "03/01/2023", ... "29/01/2023","30/01/2023",\n        OT:\n            OT schedules can be and the working_days_list is "03/01/2023", "06/01/2023" and "24/01/2023"\n            # TODO: working day list needs to be claculated for payroll_type is Over Time\n    '
    working_days_list = [add_days(getdate(start_date), days=day) for day in range(0, working_days)]
    '\n        Calculate working days based on the configuration of include_holidays_in_total_working_days\n        If include_holidays_in_total_working_days is true then,\n            set working_days by minusing the length of holidays from the working days\n            set working_days_list will update by removing the holiday dates from the working_days_list\n    '
    if not cint(include_holidays_in_total_working_days):
        working_days_list = [i for i in working_days_list if i not in holidays]
        working_days -= len(holidays)
        if working_days < 0:
            frappe.throw(_('There are more holidays than working days this month.'))
    if not payroll_based_on:
        frappe.throw(_('Please set Payroll based on in Payroll settings'))
    if payroll_based_on == 'Attendance':
        actual_lwp, absent = self.calculate_lwp_ppl_and_absent_days_based_on_attendance(holidays, relieving_date)
        self.absent_days = absent
    else:
        actual_lwp = self.calculate_lwp_or_ppl_based_on_leave_application(holidays, working_days_list, relieving_date)
    if not lwp:
        lwp = actual_lwp
    elif lwp != actual_lwp:
        frappe.msgprint(_('Leave Without Pay does not match with approved {} records').format(payroll_based_on))
    self.leave_without_pay = lwp
    self.total_working_days = working_days
    payment_days = working_days
    if flt(payment_days) > flt(lwp):
        self.payment_days = flt(payment_days) - flt(lwp)
        if payroll_based_on == 'Attendance':
            self.payment_days -= flt(absent)
        consider_unmarked_attendance_as = frappe.db.get_value('Payroll Settings', None, 'consider_unmarked_attendance_as') or 'Present'
        if payroll_based_on == 'Attendance' and consider_unmarked_attendance_as == 'Absent':
            unmarked_days = self.get_unmarked_days(include_holidays_in_total_working_days)
            self.absent_days += unmarked_days
            self.payment_days -= unmarked_days
    else:
        self.payment_days = 0

@frappe.whitelist()
def get_ot_days(employee, start_date, end_date):
    ot_schedule = frappe.get_all('Employee Schedule', filters={'date': ['between', [start_date, end_date]], 'employee': employee, 'roster_type': 'Over-Time'}, fields=['COUNT(*) as working_ot_days'])[0].working_ot_days
    return ot_schedule

def get_unmarked_days_based_on_doj_or_relieving(self, unmarked_days, include_holidays_in_total_working_days, start_date, end_date):
    """
    Exclude days before DOJ or after
    Relieving Date from unmarked days
    """
    from erpnext.setup.doctype.employee.employee import is_holiday
    if include_holidays_in_total_working_days:
        unmarked_days -= date_diff(end_date, start_date) + 1
    else:
        scheduled_days = get_scheduled_days(self.employee, start_date, end_date)
        for days in range(date_diff(end_date, start_date) + 1):
            date = add_days(end_date, -days)
            if not is_holiday(self.employee, date) and date not in scheduled_days:
                unmarked_days -= 1
    return unmarked_days

def calculate_lwp_ppl_and_absent_days(employee, start_date, end_date, holidays):
    lwp = 0
    absent = 0
    daily_wages_fraction_for_half_day = flt(frappe.db.get_value('Payroll Settings', None, 'daily_wages_fraction_for_half_day')) or 0.5
    leave_types = frappe.get_all('Leave Type', or_filters=[['is_ppl', '=', 1], ['is_lwp', '=', 1]], fields=['name', 'is_lwp', 'is_ppl', 'fraction_of_daily_salary_per_leave', 'include_holiday'])
    leave_type_map = {}
    for leave_type in leave_types:
        leave_type_map[leave_type.name] = leave_type
    attendances = frappe.db.sql('\n        SELECT attendance_date, status, leave_type\n        FROM `tabAttendance`\n        WHERE\n            status in ("Absent", "Half Day", "On leave")\n            AND employee = %s\n            AND docstatus = 1\n            AND attendance_date between %s and %s\n    ', values=(employee, start_date, end_date), as_dict=1)
    for d in attendances:
        if d.status in ('Half Day', 'On Leave') and d.leave_type and (d.leave_type not in leave_type_map.keys()):
            continue
        if formatdate(d.attendance_date, 'yyyy-mm-dd') in holidays:
            if d.status == 'Absent' or (d.leave_type and d.leave_type in leave_type_map.keys() and (not leave_type_map[d.leave_type]['include_holiday'])):
                continue
        if d.leave_type:
            fraction_of_daily_salary_per_leave = leave_type_map[d.leave_type]['fraction_of_daily_salary_per_leave']
        if d.status == 'Half Day':
            equivalent_lwp = 1 - daily_wages_fraction_for_half_day
            if d.leave_type in leave_type_map.keys() and leave_type_map[d.leave_type]['is_ppl']:
                equivalent_lwp *= fraction_of_daily_salary_per_leave if fraction_of_daily_salary_per_leave else 1
            lwp += equivalent_lwp
        elif d.status == 'On Leave' and d.leave_type and (d.leave_type in leave_type_map.keys()):
            equivalent_lwp = 1
            if leave_type_map[d.leave_type]['is_ppl']:
                equivalent_lwp *= fraction_of_daily_salary_per_leave if fraction_of_daily_salary_per_leave else 1
            lwp += equivalent_lwp
        elif d.status == 'Absent':
            absent += 1
    return (lwp, absent)

