    except Exception:
        error_message = message_log
    error_message += '\n' + _('Check Error Log {0} for more details.').format(get_link_to_form('Error Log', error_log.name))
    payroll_entry.db_set({'error_message': error_message, 'status': 'Failed'})

def create_salary_slips_for_employees(employees, payroll_entry, publish_progress=True):
    from one_fm.api.doc_methods.salary_slip import get_ot_days
    try:
        payroll_entry = frappe.get_doc('Payroll Entry', payroll_entry.name)
        args = frappe._dict({'salary_slip_based_on_timesheet': payroll_entry.salary_slip_based_on_timesheet, 'payroll_frequency': payroll_entry.payroll_frequency, 'company': payroll_entry.company, 'posting_date': payroll_entry.posting_date, 'deduct_tax_for_unclaimed_employee_benefits': payroll_entry.deduct_tax_for_unclaimed_employee_benefits, 'deduct_tax_for_unsubmitted_tax_exemption_proof': payroll_entry.deduct_tax_for_unsubmitted_tax_exemption_proof, 'exchange_rate': payroll_entry.exchange_rate, 'currency': payroll_entry.currency, 'payroll_entry': payroll_entry.name, 'payroll_type': payroll_entry.payroll_type})
        salary_slips_exist_for = get_existing_salary_slips(employees, args)
        count = 0
        start_date = payroll_entry.start_date
        end_date = payroll_entry.end_date
        salary_slip_chunk = []
        chunk_counter = 0
        employees_list = seperate_salary_slip(employees, start_date, end_date)
        if payroll_entry.payroll_type == 'Over-Time':
            for emp in employees_list:
                if get_ot_days(emp['employee'], emp['start_date'], emp['end_date']) == 0:
                    employees_list.remove(emp)
        if len(employees_list) < 30:
            for emp in employees_list:
                if emp['employee'] not in salary_slips_exist_for:
                    args.update({'doctype': 'Salary Slip'})
                    args.update(emp)
                    frappe.get_doc(args).insert()
                    count += 1
                    if publish_progress:
                        frappe.publish_progress(count * 100 / len(set(employees) - set(salary_slips_exist_for)), title=_('Creating Salary Slips...'))
        else:
            for emp in employees_list:
                if emp['employee'] not in salary_slips_exist_for:
                    args.update({'doctype': 'Salary Slip'})
                    args.update(emp)
                    salary_slip_chunk.append(frappe.get_doc(args))
                    chunk_counter += 1
                    if len(salary_slip_chunk) >= 30:
                        frappe.enqueue(create_salary_slip_chunk, slips=salary_slip_chunk.copy(), queue='long')
                        salary_slip_chunk = []
                        chunk_counter = 0
            if salary_slip_chunk:
                frappe.enqueue(create_salary_slip_chunk, slips=salary_slip_chunk, queue='long')
        payroll_entry.db_set({'status': 'Submitted', 'salary_slips_created': 1, 'error_message': ''})
        if salary_slips_exist_for:
            frappe.msgprint(_('Salary Slips already exist for employees {}, and will not be processed by this payroll.').format(frappe.bold(', '.join((emp for emp in salary_slips_exist_for)))), title=_('Message'), indicator='orange')
    except Exception as e:
        frappe.db.rollback()
        log_payroll_failure('creation', payroll_entry, e)
    finally:
        frappe.db.commit()
        frappe.publish_realtime('completed_salary_slip_creation')

def create_salary_slip_chunk(slips):
    for slip in slips:
        slip.insert()
        slip.save()

