@frappe.whitelist()
def get_current_shift(employee):
    """This function is to return employee's current Shift,
	based on Shift Assignment. 
	Args:
		employee (str): Employee's ERP ID
	Returns:
		string: Operation Shift of the assigned shift if it exist.
	"""
    try:
        current_datetime = now_datetime()
        shift = frappe.get_last_doc('Shift Assignment', filters={'employee': employee}, order_by='creation desc')
        if shift:
            before_time, after_time = frappe.get_value('Shift Type', shift.shift_type, ['begin_check_in_before_shift_start_time', 'allow_check_out_after_shift_end_time'])
            if shift.start_datetime and shift.end_datetime:
                start_time = shift.start_datetime - datetime.timedelta(minutes=before_time)
                end_time = shift.end_datetime + datetime.timedelta(minutes=after_time)
                if start_time <= current_datetime <= end_time:
                    return shift
    except Exception as e:
        print(frappe.get_traceback())
        return frappe.utils.response.report_error(e.http_status_code)

