            validation_logs.append('Please select either the project end date or set a custom date. You cannot set both!')
        emp_tuple = str(employee_list).replace('[', '(').replace(']', ')')
        if not cint(request_employee_schedule) and 'Projects Manager' not in user_roles and ('Operations Manager' not in user_roles):
            all_employee_shift_query = frappe.db.sql("\n                SELECT DISTINCT es.shift, s.supervisor\n                FROM `tabEmployee Schedule` es JOIN `tabOperations Shift` s ON es.shift = s.name\n                WHERE\n                es.date BETWEEN '{start_date}' AND '{end_date}'\n                AND es.employee_availability='Working' AND es.employee IN {emp_tuple}\n                GROUP BY es.shift\n            ".format(start_date=start_date, end_date=end_date, emp_tuple=emp_tuple), as_dict=1)
        if len(validation_logs) > 0:
            frappe.log_error(str(validation_logs), 'Roster Schedule')
            frappe.throw(str(validation_logs))
        else:
            resp = extreme_schedule(employees=employees, start_date=start_date, end_date=end_date, shift=shift, operations_role=operations_role, otRoster=otRoster, keep_days_off=keep_days_off, day_off_ot=day_off_ot, request_employee_schedule=request_employee_schedule, employee_list=employee_list, repeat_days=repeat_days, day_off=day_off)
            update_roster(key='roster_view')
            print(resp)
            if type(resp) == dict:
                resp = frappe._dict(resp)
                response('success', 200, {'message': 'Successfully rostered employees'})
            response(resp.status, resp.code, resp.data)
    except Exception as e:
        frappe.log_error(frappe.get_traceback(), 'Schedule Roster')
