def send_token_via_email(user, token, otp_secret, otp_issuer, subject=None, message=None):
    """Send token to user as email."""
    user_email = frappe.db.get_value('Employee', {'user_id': user}, 'personal_email')
    if not user_email:
        return False
    hotp = pyotp.HOTP(otp_secret)
    otp = hotp.at(int(token))
    template_args = {'otp': otp, 'otp_issuer': otp_issuer}
    if not subject:
        subject = get_email_subject_for_2fa(template_args)
    if not message:
        message = get_email_body_for_2fa(template_args)
    email_args = {'recipients': user_email, 'sender': None, 'subject': subject, 'message': message, 'header': [_('Verfication Code'), 'blue'], 'delayed': False, 'retry': 3}
    enqueue(method=sendemail, queue='short', timeout=300, event=None, is_async=True, job_name=None, now=False, **email_args)
    return True

