def get_passport_data(image_path):
    try:
        mindee_client = ClientV2(api_key=frappe.local.conf.mindee_passport_api)
        passport_model_id = frappe.local.conf.passport_model_id
        input_doc = PathInput(image_path)
        passport_params = InferenceParameters(model_id=passport_model_id, rag=None, raw_text=None, polygon=None, confidence=None)
        passport_response = mindee_client.enqueue_and_get_inference(input_doc, passport_params)
        passport_fields: dict = passport_response.inference.result.fields
        result_dict = frappe._dict(dict(birth_place=passport_fields.place_of_birth.value, expiry_date=passport_fields.date_of_expiry.value, given_names=passport_fields.given_names.value, mrz1=passport_fields.mrz_line_1.value, mrz2=passport_fields.mrz_line_2.value, birth_date=passport_fields.date_of_birth.value, country=passport_fields.issuing_country.value, gender=passport_fields.gender.value, id_number=passport_fields.passport_number.value, issuance_date=passport_fields.date_of_issue.value, surname=passport_fields.surnames.value))
    except Exception as e:
        frappe.log_error(frappe.get_traceback(), 'Mindee')
        return frappe._dict({})
    return result_dict

def get_passport_front_text(image_path, client):
    with io.open(image_path, 'rb') as image_file:
        content = image_file.read()
    image = vision.Image(content=content)
    response = client.text_detection(image=image)
    f = open('demofilesg.txt', 'a')
    f.write(str(response))
    f.close()
    texts = response.text_annotations
    result = {}
    assemble = {}
    index = 0
    for index in range(1, len(texts)):
        assemble[index] = texts[index].description
    text_length = len(texts)
    fuzzy = False
    result['Passport_Front'] = image_path
    if text_length >= 5:
        if is_date(texts[text_length - 4].description, fuzzy):
            result['Passport_Date_of_Issue'] = datetime.datetime.strptime(texts[text_length - 4].description, '%d/%m/%Y').strftime('%Y-%m-%d')
        else:
            result['Passport_Date_of_Issue'] = ''
        if is_date(texts[text_length - 3].description, fuzzy):
            result['Passport_Date_of_Expiry'] = datetime.datetime.strptime(texts[text_length - 3].description, '%d/%m/%Y').strftime('%Y-%m-%d')
        else:
            result['Passport_Date_of_Expiry'] = ''
        mrz = texts[text_length - 1].description
        result['Passport_Number'] = mrz.split('<')[0]
    return result

def get_passport_back_text(image_path, client):
    with io.open(image_path, 'rb') as image_file:
        content = image_file.read()
    image = vision.Image(content=content)
    response = client.text_detection(image=image)
    texts = response.text_annotations
    result = {}
