def parse_names(input_string: str) -> tuple:
    first_name = ''
    last_name = ''
    second_name = ''
    third_name = ''
    fourth_name = ''
    if input_string:
        names = input_string.split()
        num_names = len(names)
        if num_names > 0:
            first_name = names[0]
        if num_names > 1:
            last_name = names[-1]
        if num_names == 3:
            second_name = names[1]
        elif num_names == 4:
            second_name = names[1]
            third_name = names[2]
        elif num_names > 4:
            second_name = names[1]
            third_name = names[2]
            fourth_name = names[3]
    return (first_name, second_name, third_name, fourth_name, last_name)

