def get_transaction_list(doctype, txt=None, filters=None, limit_start=0, limit_page_length=20, order_by='modified'):
    user = frappe.session.user
    ignore_permissions = False
    if not filters:
        filters = []
    if doctype in ['Supplier Quotation', 'Purchase Invoice']:
        filters.append((doctype, 'docstatus', '<', 2))
    else:
        filters.append((doctype, 'docstatus', '=', 1))
    if user != 'Guest' and is_website_user() or doctype == 'Request for Supplier Quotation':
        parties_doctype = 'Request for Supplier Quotation Supplier' if doctype == 'Request for Supplier Quotation' else doctype
        customers, suppliers = get_customers_suppliers(parties_doctype, user)
        if customers:
            if doctype == 'Quotation':
                filters.append(('quotation_to', '=', 'Customer'))
                filters.append(('party_name', 'in', customers))
            else:
                filters.append(('customer', 'in', customers))
        elif suppliers:
            filters.append(('supplier', 'in', suppliers))
        else:
            return []
        if doctype == 'Request for Supplier Quotation':
            parties = customers or suppliers
            return rfq_transaction_list(parties_doctype, doctype, parties, limit_start, limit_page_length)
        ignore_permissions = True
    transactions = get_list_for_transactions(doctype, txt, filters, limit_start, limit_page_length, fields='name', ignore_permissions=ignore_permissions, order_by='modified desc')
    return post_process(doctype, transactions)

def get_list_for_transactions(doctype, txt, filters, limit_start, limit_page_length=20, ignore_permissions=False, fields=None, order_by=None):
    """ Get List of transactions like Invoices, Orders """
    from frappe.www.list import get_list
    meta = frappe.get_meta(doctype)
    data = []
    or_filters = []
    for d in get_list(doctype, txt, filters=filters, fields='name', limit_start=limit_start, limit_page_length=limit_page_length, ignore_permissions=ignore_permissions, order_by='modified desc'):
        data.append(d)
    if txt:
        if meta.get_field('items'):
            if meta.get_field('items').options:
                child_doctype = meta.get_field('items').options
                for item in frappe.get_all(child_doctype, {'item_name': ['like', '%' + txt + '%']}):
                    child = frappe.get_doc(child_doctype, item.name)
                    or_filters.append([doctype, 'name', '=', child.parent])
    if or_filters:
        for r in frappe.get_list(doctype, fields=fields, filters=filters, or_filters=or_filters, limit_start=limit_start, limit_page_length=limit_page_length, ignore_permissions=ignore_permissions, order_by=order_by):
            data.append(r)
    return data

def rfq_transaction_list(parties_doctype, doctype, parties, limit_start, limit_page_length):
    data = frappe.db.sql("select distinct parent as name, supplier from `tab{doctype}`\n\t\t\twhere supplier = '{supplier}' and docstatus=1  order by modified desc limit {start}, {len}".format(doctype=parties_doctype, supplier=parties[0], start=limit_start, len=limit_page_length), as_dict=1)
    return post_process(doctype, data)

