def create_onboarding_from_job_offer(job_offer):
    if job_offer.status == 'Accepted':
        if not job_offer.onboarding_officer:
            frappe.msgprint(_('Please Select Onboarding Officer to Create Onboard Employee'))
        elif not frappe.db.exists('Onboard Employee', {'job_offer': job_offer.name}):
            fields = ['employee_grade', 'job_applicant', 'is_g2g_fees_needed', 'is_residency_fine_needed', 'g2g_fee_amount', 'is_residency_fine_needed', 'shift_working']
            one_fm_fields = ['salary_structure', 'job_offer_total_salary', 'provide_salary_advance', 'salary_advance_amount', 'provide_accommodation_by_company', 'provide_transportation_by_company']
            o_employee = frappe.new_doc('Onboard Employee')
            o_employee.job_offer = job_offer.name
            o_employee.reports_to = job_offer.reports_to
            o_employee.date_of_joining = job_offer.estimated_date_of_joining
            o_employee.employment_type = job_offer.employment_type
            o_employee.operations_shift = job_offer.operations_shift
            for d in fields:
                o_employee.set(d, job_offer.get(d))
            for od in one_fm_fields:
                o_employee.set(od, job_offer.get('one_fm_' + od))
            if job_offer.one_fm_salary_details:
                o_employee_salary_details = o_employee.append('salary_details')
                for salary_detail in job_offer.one_fm_salary_details:
                    o_employee_salary_details.salary_component = salary_detail.salary_component
                    o_employee_salary_details.amount = salary_detail.amount
            if job_offer.job_applicant:
                fields = ['email_id', 'department', 'project', 'source', 'nationality_no', 'nationality_subject', 'date_of_naturalization']
                one_fm_fields = ['applicant_is_overseas_or_local', 'is_transferable', 'designation', 'agency', 'gender', 'religion', 'date_of_birth', 'erf', 'height', 'place_of_birth', 'marital_status', 'nationality', 'contact_number', 'secondary_contact_number', 'passport_number', 'passport_holder_of', 'passport_issued', 'passport_expire', 'passport_type', 'visa_type', 'civil_id', 'cid_expire', 'is_uniform_needed_for_this_job', 'shoulder_width', 'waist_size', 'shoe_size']
                job_applicant = frappe.get_doc('Job Applicant', job_offer.job_applicant)
                for d in fields:
                    o_employee.set(d, job_applicant.get(d))
                for od in one_fm_fields:
                    if od == 'civil_id':
                        o_employee.set(od, job_applicant.get('one_fm_cid_number'))
                    else:
                        o_employee.set(od, job_applicant.get('one_fm_' + od))
                o_employee.set('first_name_in_arabic', job_applicant.get('one_fm_first_name_in_arabic') or job_applicant.get('one_fm_first_name'))
                o_employee.set('second_name_in_arabic', job_applicant.get('one_fm_second_name_in_arabic') or '')
                o_employee.set('third_name_in_arabic', job_applicant.get('one_fm_third_name_in_arabic') or '')
                o_employee.set('forth_name_in_arabic', job_applicant.get('one_fm_forth_name_in_arabic') or '')
                o_employee.set('last_name_in_arabic', job_applicant.get('one_fm_last_name_in_arabic') or job_applicant.get('one_fm_last_name'))
                for applicant_document in job_applicant.one_fm_documents_required:
                    doc_required = o_employee.append('applicant_documents')
                    fields = ['document_required', 'attach', 'required_when', 'or_required_when', 'type_of_copy', 'or_type_of_copy', 'not_mandatory']
                    for field in fields:
                        doc_required.set(field, applicant_document.get(field))
            if job_offer.one_fm_erf:
                tools_needed_for_work = False
                if frappe.db.exists('ERF Tool Request Item', {'parent': job_offer.one_fm_erf}):
                    tools_needed_for_work = True
                o_employee.tools_needed_for_work = tools_needed_for_work
            o_employee.save(ignore_permissions=True)
            args = {'assign_to': [job_offer.onboarding_officer], 'doctype': o_employee.doctype, 'name': o_employee.name, 'description': _('Employee Onboarding')}
            assign_to.add(args)
            assign_to.close_all_assignments(job_offer.doctype, job_offer.name)

