@frappe.whitelist()
def create_interview_feedback(data, interview_name, interviewer, job_applicant, method='save', feedback_exists=False):
    if isinstance(data, string_types):
        data = frappe._dict(json.loads(data))
    if frappe.session.user != interviewer:
        frappe.throw(_('Only Interviewer Are allowed to submit Interview Feedback'))
    interview_feedback = False
    if feedback_exists:
        interview_feedback = frappe.get_doc('Interview Feedback', feedback_exists)
    else:
        interview_feedback = frappe.new_doc('Interview Feedback')
        interview_feedback.interview = interview_name
        interview_feedback.interviewer = interviewer
        interview_feedback.job_applicant = job_applicant
    if interview_feedback:
        for d in data.skill_set:
            d = frappe._dict(d)
            if not d.parent:
                interview_feedback.append('skill_assessment', {'skill': d.skill, 'rating': d.rating})
            else:
                for skill in interview_feedback.skill_assessment:
                    if skill.name == d.name:
                        skill.rating = d.rating
        if data.questions:
            for dq in data.questions:
                dq = frappe._dict(dq)
                if not dq.parent:
                    interview_feedback.append('interview_question_assessment', {'questions': dq.questions, 'answer': dq.answer, 'weight': dq.weight, 'applicant_answer': dq.applicant_answer, 'score': dq.score})
                else:
                    for question in interview_feedback.interview_question_assessment:
                        if question.name == dq.name:
                            question.applicant_answer = dq.applicant_answer
                            question.score = dq.score
        interview_feedback.result = data.result
        interview_feedback.feedback = data.feedback
        if method == 'save':
            interview_feedback.flags.ignore_mandatory = True
        interview_feedback.save()
        if method == 'submit':
            interview_feedback.submit()
        frappe.msgprint(_('{1} Interview Feedback {0} successfully!').format(get_link_to_form('Interview Feedback', interview_feedback.name), method.title()))

def calculate_interview_feedback_average_rating(doc, method):
    total_rating = 0
    for d in doc.skill_assessment:
        if d.rating:
            total_rating += d.rating
    total_skill_rating = flt(total_rating / len(doc.skill_assessment) if len(doc.skill_assessment) else 0)
    total_question_rating = 0
    if doc.interview_question_assessment and len(doc.interview_question_assessment) > 0:
        total_rating = 0
        for d in doc.interview_question_assessment:
            d.weight = d.weight if d.weight else 0
            if d.weight > 0 and d.score:
                total_rating += get_rating_from_the_score(d.score, d.weight)
        total_question_rating = flt(total_rating / len(doc.interview_question_assessment))
    if total_question_rating > 0:
        doc.average_rating = (total_skill_rating + total_question_rating) / 2
    else:
        doc.average_rating = total_skill_rating

def get_rating_from_the_score(score, weight):
    score_per = score / weight
    return score_per if score_per else 0

