    return target_doc

def validate(self):
    self._prev = frappe._dict({'contact_date': frappe.db.get_value('Lead', self.name, 'contact_date') if not cint(self.is_new()) else None, 'ends_on': frappe.db.get_value('Lead', self.name, 'ends_on') if not cint(self.is_new()) else None, 'contact_by': frappe.db.get_value('Lead', self.name, 'contact_by') if not cint(self.is_new()) else None})
    self.check_email_id_is_unique()
    self.check_mobile_no_is_unique()
    if self.contact_date and getdate(self.contact_date) < getdate(nowdate()):
        frappe.throw(_('Next Contact Date cannot be in the past'))
    if self.ends_on and self.contact_date and (getdate(self.ends_on) < getdate(self.contact_date)):
        frappe.throw(_('Ends On date cannot be before Next Contact Date.'))

def check_email_id_is_unique(self):
    if self.email_id:
        duplicate_leads = frappe.get_all('Applicant Lead', filters={'email_id': self.email_id, 'name': ['!=', self.name]})
        duplicate_leads = [lead.name for lead in duplicate_leads]
        if duplicate_leads:
            frappe.throw(_('Email Address must be unique, already exists for {0}').format(comma_and(duplicate_leads)), frappe.DuplicateEntryError)

def check_mobile_no_is_unique(self):
    if self.mobile_no:
        duplicate_leads = frappe.get_all('Applicant Lead', filters={'mobile_no': self.mobile_no, 'name': ['!=', self.name]})
        duplicate_leads = [lead.name for lead in duplicate_leads]
        if duplicate_leads:
