    progress_wf_list = {'Open': 0, 'Submitted for Applicant Review': 10, 'Applicant Signed': 20, 'Applicant not Signed': 100, 'Submitted to Legal': 40, 'Send to Authorised Signatory': 70, 'Completed': 100, 'Cancelled': 0}
    if self.workflow_state in progress_wf_list:
        self.progress = progress_wf_list[self.workflow_state]

