def send_google_chat_notification(doc, method):
    """Hangouts Chat incoming webhook to send the Issues Created, in Card Format."""
    default_api_integration = frappe.get_doc('Default API Integration')
    if not default_api_integration:
        return
    if not default_api_integration.integration_setting:
        return
    google_chat = frappe.get_doc('API Integration', [i for i in default_api_integration.integration_setting if i.app_name == 'Google Chat'][0].app_name)
    if google_chat.active:
        url = f"{google_chat.url}/spaces/{google_chat.api_parameter[0].get_password('value')}/messages?key={google_chat.get_password('api_key')}&token={google_chat.get_password('api_token')}"
        message = f'<b>A new Issue has been created</b><br>\n            <i>Details:</i> <br>\n            Subject: {doc.subject} <br>\n            Name: {doc.name} <br>\n            Raised By (Email): {doc.raised_by} <br>\n            Body: {doc.description}<br>\n            '
        bot_message = {'cards_v2': [{'card_id': 'IssueCard', 'card': {'sections': [{'widgets': [{'textParagraph': {'text': message}}, {'buttonList': {'buttons': [{'text': 'Open Document', 'onClick': {'openLink': {'url': frappe.utils.get_url(doc.get_url())}}}]}}]}]}}]}
        message_headers = {'Content-Type': 'application/json; charset=UTF-8'}
        http_obj = Http()
        response = http_obj.request(uri=url, method='POST', headers=message_headers, body=dumps(bot_message))

def send_open_issue_count_to_google_chat_notification(doc, method):
    query = frappe.db.sql("\n\t\tSELECT COUNT(status) as status_count FROM `tabIssue` WHERE status='Open' AND DATEDIFF(NOW(), modified)>0;\n\t", as_dict=1)
    if query[0].status_count:
        default_api_integration = frappe.get_doc('Default API Integration')
        google_chat = frappe.get_doc('API Integration', [i for i in default_api_integration.integration_setting if i.app_name == 'Google Chat'][0].app_name)
        url = f"{google_chat.url}/spaces/{google_chat.api_parameter[0].get_password('value')}/messages?key={google_chat.get_password('api_key')}&token={google_chat.get_password('api_token')}"
        message = f'<b>There are {query[0].status_count} open issue(s) that have not been replied to in the last 24 hour</b><br>'
        bot_message = {'cards_v2': [{'card_id': 'IssueCard', 'card': {'sections': [{'widgets': [{'textParagraph': {'text': message}}]}]}}]}
        message_headers = {'Content-Type': 'application/json; charset=UTF-8'}
        http_obj = Http()
        response = http_obj.request(uri=url, method='POST', headers=message_headers, body=dumps(bot_message))

