def create_workflow_action_master(action_masters):
    """
    Create or update Workflow Action Masters.

    Args:
        action_masters (str or list[str]): Action(s) to be created if not already present.

    Returns:
        None
    """
    if isinstance(action_masters, str):
        action_masters = [action_masters]
    if not isinstance(action_masters, list):
        frappe.log_error('Workflow actions must be a list or string.')
        return
    action_masters = list(set([a.strip() for a in action_masters if isinstance(a, str) and a.strip()]))
    if not action_masters:
        return
    try:
        existing_actions = frappe.get_all('Workflow Action Master', filters={'workflow_action_name': ['in', action_masters]}, pluck='workflow_action_name')
        to_create = set(action_masters) - set(existing_actions)
        for action in to_create:
            frappe.get_doc({'doctype': 'Workflow Action Master', 'workflow_action_name': action}).insert(ignore_permissions=True)
    except Exception as e:
        frappe.log_error(title='Workflow Action Master Error', message=f'Error while creating workflow actions:\n{frappe.get_traceback()}')

@frappe.whitelist()
def accommodation_qr_code_live_details(docname):
    doctype = False
    if frappe.db.exists('Bed', {'name': docname}):
        doctype = 'Bed'
    elif frappe.db.exists('Accommodation Space', {'name': docname}):
        doctype = 'Accommodation Space'
    elif frappe.db.exists('Accommodation Unit', {'name': docname}):
        doctype = 'Accommodation Unit'
    elif frappe.db.exists('Accommodation', {'name': docname}):
        doctype = 'Accommodation'
    if doctype:
        format = doctype + ' QR Details'
        if not frappe.db.exists('Print Format', {'name': doctype + ' QR Details'}):
            format = None
        return download_pdf(doctype, docname, format=format, doc=None, no_letterhead=0)

