        columns.append(_('Unit') + ':Link/Accommodation Unit:80')
    columns.append(_('Meter Type') + ':Data:100')
    columns.append(_('Meter Ref') + ':Data:100')
    months = ['Jan', 'Feb', 'March', 'April', 'May', 'June', 'July', 'Aug', 'Sept', 'Oct', 'Nov', 'Dec']
