                query = '\n\t\t\t\t\t\tupdate\n\t\t\t\t\t\t\ttabBed\n\t\t\t\t\t\tset\n\t\t\t\t\t\t\tdisabled=%(disabled)s, bed_type=%(bed_type)s, gender=%(gender)s\n\t\t\t\t\t\twhere\n\t\t\t\t\t\t\tname=%(bed)s\n\t\t\t\t\t'
                filters = {'disabled': bed.disabled, 'gender': bed.gender, 'bed_type': bed.bed_type, 'bed': bed.bed}
                frappe.db.sql(query, filters)

