    contact_list_fields = {'owner_contact_list': 'owner_contact', 'legal_representative_contact_list': 'legal_representative_contact', 'other_primary_point_of_contact_list': 'other_primary_point_of_contact', 'legal_authorization_contact_list': 'legal_authorization_contact'}
    for list_field in contact_list_fields:
        contact_list = []
        contact_list = frappe.get_all('Contact', filters={'name': doc.get(contact_list_fields[list_field])}, fields=['*'])
        for contact in contact_list:
            contact['email_ids'] = frappe.get_list('Contact Email', filters={'parenttype': 'Contact', 'parent': contact.name, 'is_primary': 0}, fields=['email_id'])
            contact['phone_nos'] = frappe.get_list('Contact Phone', filters={'parenttype': 'Contact', 'parent': contact.name, 'is_primary_phone': 0, 'is_primary_mobile_no': 0}, fields=['phone'])
            if contact.address:
                from frappe.contacts.doctype.address.address import get_condensed_address
                address = frappe.get_doc('Address', contact.address)
                contact['address'] = get_condensed_address(address)
        contact_list = sorted(contact_list, key=functools.cmp_to_key(lambda a, b: int(a.is_primary_contact - b.is_primary_contact) or (1 if a.modified - b.modified else 0)), reverse=True)
        doc.set_onload(list_field, contact_list)

