def get_depreciation_accounts(asset, project=None):
    fixed_asset_account = accumulated_depreciation_account = depreciation_expense_account = project_depreciation_expense_account = None
    accounts = frappe.db.get_value('Asset Category Account', filters={'parent': asset.asset_category, 'company_name': asset.company}, fieldname=['fixed_asset_account', 'accumulated_depreciation_account', 'indirect_depreciation_expense_account', 'direct_depreciation_expense_account'], as_dict=1)
    if accounts:
        fixed_asset_account = accounts.fixed_asset_account
        accumulated_depreciation_account = accounts.accumulated_depreciation_account
        depreciation_expense_account = accounts.indirect_depreciation_expense_account
        project_depreciation_expense_account = accounts.direct_depreciation_expense_account
    if not accumulated_depreciation_account or not depreciation_expense_account:
        accounts = frappe.get_cached_value('Company', asset.company, ['accumulated_depreciation_account', 'depreciation_expense_account'])
        if not accumulated_depreciation_account:
            accumulated_depreciation_account = accounts[0]
        if not depreciation_expense_account:
            depreciation_expense_account = accounts[1]
    if asset.location and project:
        if not project_depreciation_expense_account:
            frappe.throw(_('Please set Indirect Depreciation Expense Account in Asset Category {0}.').format(asset.asset_category))
        else:
            depreciation_expense_account = project_depreciation_expense_account
    if not fixed_asset_account or not accumulated_depreciation_account or (not depreciation_expense_account):
        frappe.throw(_('Please set Depreciation related Accounts in Asset Category {0} or Company {1}').format(asset.asset_category, asset.company))
    return (fixed_asset_account, accumulated_depreciation_account, depreciation_expense_account)

