            args = {'doctype': 'Journal Entry', 'naming_series': journal_series, 'company': doc.company, 'voucher_type': 'Journal Entry', 'posting_date': doc.posting_date, 'user_remark': 'Invoice settlement for Sales Invoice {}'.format(doc.name)}
            journal_dict = frappe._dict(args)
