    try:
        sales_invoice.flags.ignore_permissions = True
        sales_invoice.update({'customer': sales_invoice.customer, 'set_posting_time': sales_invoice.set_posting_time, 'project': sales_invoice.project, 'contracts': sales_invoice.contracts, 'selling_price_list': sales_invoice.selling_price_list, 'items': sales_invoice.items, 'timesheets': sales_invoice.timesheets}).insert()
    except Exception as e:
