        if actual_service_list:
            if site_wise_option != 'Add With Hours':
                for item in actual_service_list:
                    if sales_invoice.items:
                        flag = 0
                        for i in sales_invoice.items:
                            if i.item_code == item['item_code'] and i.days == item['days'] and (i.site == item['site']):
                                flag = 1
                                i.qty = i.qty + 1
                                i.total_hours += item['days'] * contract_item.shift_hours
                                i.hours_worked += item['days'] * contract_item.shift_hours
                        if flag == 0:
                            sales_invoice.append('items', {'item_code': item['item_code'], 'qty': 1, 'rate': item['billing_amount'], 'site': site, 'days': item['days'], 'basic_hours': contract_item.shift_hours, 'hourly_rate': hourly_rate, 'monthly_rate': monthly_rate, 'total_hours': item['days'] * contract_item.shift_hours, 'hours_worked': item['days'] * contract_item.shift_hours, 'income_account': income_account, 'cost_center': cost_center})
                    else:
                        sales_invoice.append('items', {'item_code': item['item_code'], 'qty': 1, 'rate': item['billing_amount'], 'site': site, 'days': item['days'], 'basic_hours': contract_item.shift_hours, 'hourly_rate': hourly_rate, 'monthly_rate': monthly_rate, 'total_hours': item['days'] * contract_item.shift_hours, 'hours_worked': item['days'] * contract_item.shift_hours, 'income_account': income_account, 'cost_center': cost_center})
            else:
                for item in actual_service_list:
                    if sales_invoice.items:
                        flag = 0
                        for i in sales_invoice.items:
                            if i.item_code == item['item_code'] and i.site == item['site']:
                                flag = 1
                                i.qty = i.qty + 1
                                i.rate = (i.amount + item['billing_amount']) / float(i.qty)
                                i.total_hours += total_working_days * contract_item.shift_hours
                                i.hours_worked += item['days'] * contract_item.shift_hours
                        if flag == 0:
                            sales_invoice.append('items', {'item_code': item['item_code'], 'qty': 1, 'rate': item['billing_amount'], 'amount': item['billing_amount'], 'site': site, 'days': total_working_days, 'basic_hours': contract_item.shift_hours, 'hourly_rate': hourly_rate, 'monthly_rate': monthly_rate, 'total_hours': total_working_days * contract_item.shift_hours, 'hours_worked': item['days'] * contract_item.shift_hours, 'income_account': income_account, 'cost_center': cost_center})
                    else:
                        sales_invoice.append('items', {'item_code': item['item_code'], 'qty': 1, 'rate': item['billing_amount'], 'amount': item['billing_amount'], 'site': site, 'days': total_working_days, 'basic_hours': contract_item.shift_hours, 'hourly_rate': hourly_rate, 'monthly_rate': monthly_rate, 'total_hours': total_working_days * contract_item.shift_hours, 'hours_worked': item['days'] * contract_item.shift_hours, 'income_account': income_account, 'cost_center': cost_center})
    return sales_invoice

def add_timesheet_details_into_invoice(sales_invoice, timesheet_details, item_code):
    timesheet_billing_amt = 0
    if timesheet_details:
        for t in timesheet_details:
            timesheet_billing_amt += t.billing_amt
            sales_invoice.append('timesheets', {'time_sheet': t.parent, 'billing_hours': t.billing_hours, 'billing_amount': t.billing_amt, 'timesheet_detail': t.name, 'item': item_code})
    sales_invoice.total_billing_amount = sales_invoice.total_billing_amount + timesheet_billing_amt
    return sales_invoice

