                else:
                    sales_invoice.append('items', {'item_code': item['item_code'], 'qty': 1, 'rate': item['billing_amount'], 'days': item['days'], 'basic_hours': contract_item.shift_hours, 'hourly_rate': hourly_rate, 'monthly_rate': monthly_rate, 'total_hours': item['days'] * contract_item.shift_hours, 'hours_worked': item['days'] * contract_item.shift_hours, 'income_account': income_account, 'cost_center': cost_center})
