def get_workdays_and_amount(project, item_code, from_time, to_time, site=None, post=None):
    filters = {'project': project, 'from_time': from_time, 'to_time': to_time, 'item_code': item_code, 'site': site, 'post': post}
    conditions = 'project = %(project)s and from_time >= %(from_time)s and to_time < %(to_time)s and activity_type in (select post_name from `tabPost Type` where sale_item = %(item_code)s)'
    if site != None:
        conditions += ' and site = %(site)s'
    if post != None:
        conditions += ' and operations_role = %(post)s'
    return frappe.db.sql("
            SELECT
                count(operations_role) as count,
                sum(billing_amount) as billing_amount
            FROM `tabTimesheet Detail`
            WHERE {conditions}
                and parenttype = 'Timesheet' and docstatus=1 and billable = 1
