def add_contracts_item_details_for_t4(sales_invoice, contract_item, first_day, last_day, income_account, cost_center):
    monthly_rate, hourly_rate = get_monthly_and_hourly_rate(sales_invoice.project, contract_item, first_day)
    total_working_days = calculate_total_working_days(sales_invoice.project, contract_item.item_code, first_day)
    inputted_qty = 0
    operations_role = frappe.db.get_value('Operations Role', {'sale_item': contract_item.item_code}, 'name')
    post_list = frappe.db.get_list('Operations Post', fields='name', filters={'post_template': operations_role, 'project': sales_invoice.project}, order_by='name')
    for post in post_list:
        actual_service_list = []
        timesheet = frappe.db.sql("select count(t.operations_role) as count, sum(billing_amount) as billing_amount\n\t \t\tfrom `tabTimesheet Detail` t where t.parenttype = 'Timesheet' and t.docstatus = 1 and t.project = %s and t.billable = 1\n\t \t\tand t.sales_invoice is null and t.operations_role = %s and t.from_time >= %s and t.to_time <= %s and t.Activity_type in (select post_name from `tabPost Type` where sale_item\n              = %s ) order by t.from_time asc", (sales_invoice.project, post.name, first_day, last_day, contract_item.item_code), as_dict=1)[0]
        if timesheet.billing_amount != None and timesheet.count > 0:
            case = {'item_code': contract_item.item_code, 'days': timesheet.count, 'billing_amount': timesheet.billing_amount}
            actual_service_list.append(case)
        if actual_service_list:
            for item in actual_service_list:
                inputted_qty = flt(item['days']) / total_working_days
                if sales_invoice.items:
                    flag = 0
                    for i in sales_invoice.items:
                        if i.item_code == item['item_code'] and i.days == item['days']:
                            flag = 1
                            i.qty = i.qty + 1
                            i.total_hours += item['days'] * contract_item.shift_hours
                            i.hours_worked += item['days'] * contract_item.shift_hours
                            i.inputted_qty += inputted_qty
                    if flag == 0:
                        sales_invoice.append('items', {'item_code': item['item_code'], 'qty': 1, 'rate': item['billing_amount'], 'days': item['days'], 'basic_hours': contract_item.shift_hours, 'hourly_rate': hourly_rate, 'monthly_rate': monthly_rate, 'total_hours': item['days'] * contract_item.shift_hours, 'hours_worked': item['days'] * contract_item.shift_hours, 'inputted_qty': inputted_qty, 'income_account': income_account, 'cost_center': cost_center})
                else:
                    sales_invoice.append('items', {'item_code': item['item_code'], 'qty': 1, 'rate': item['billing_amount'], 'days': item['days'], 'basic_hours': contract_item.shift_hours, 'hourly_rate': hourly_rate, 'monthly_rate': monthly_rate, 'total_hours': item['days'] * contract_item.shift_hours, 'hours_worked': item['days'] * contract_item.shift_hours, 'inputted_qty': inputted_qty, 'income_account': income_account, 'cost_center': cost_center})
    return sales_invoice

