@frappe.whitelist()
def user_within_site_geofence(employee, log_type, user_latitude, user_longitude):
    """ This method checks if user's given coordinates fall within the geofence radius of the user's assigned site in Shift Assigment. """
    shift_exists = get_current_shift(employee)
    if shift_exists['type'] == 'Early':
        return response('Resource Not Found', 404, None, f"You are checking in too early, checkin is allowed in {shift_exists['data']} minutes ")
    elif shift_exists['type'] == 'Late':
        return response('Resource Not Found', 404, None, f"You are checking out too late, checkout was allowed {shift_exists['data']} minutes ago ")
    elif shift_exists['type'] == 'On Time':
        shift = shift_exists['data']
    else:
        shift = None
    date = cstr(getdate())
    if shift:
        if frappe.db.exists('Shift Request', {'employee': employee, 'from_date': ['<=', date], 'to_date': ['>=', date]}):
            check_in_site, check_out_site = frappe.get_value('Shift Request', {'employee': employee, 'from_date': ['<=', date], 'to_date': ['>=', date]}, ['check_in_site', 'check_out_site'])
            if log_type == 'IN':
                location = frappe.get_list('Location', {'name': check_in_site}, ['latitude', 'longitude', 'geofence_radius'])
            else:
                location = frappe.get_list('Location', {'name': check_out_site}, ['latitude', 'longitude', 'geofence_radius'])
        elif shift.site_location:
            location = frappe.get_list('Location', {'name': shift.site_location}, ['latitude', 'longitude', 'geofence_radius'])
        elif shift.shift:
            site = frappe.get_value('Operations Shift', shift.shift, 'site')
            location = frappe.db.sql('\n\t\t\t\t\tSELECT loc.latitude, loc.longitude, loc.geofence_radius\n\t\t\t\t\tFROM `tabLocation` as loc\n\t\t\t\t\tWHERE\n\t\t\t\t\tloc.name IN (SELECT site_location FROM `tabOperations Site` where name="{site}")\n\t\t\t\t\t'.format(site=site), as_dict=1)
        if location:
            location_details = location[0]
            distance = float(haversine(location_details.latitude, location_details.longitude, user_latitude, user_longitude))
            if distance <= float(location_details.geofence_radius):
                return True
    return False

@frappe.whitelist()
def check_existing():
    """API to determine the applicable Log type.
	The api checks employee's last lcheckin log type. and determine what next log type needs to be
	Returns:
		True: The log in was "IN", so his next Log Type should be "OUT".
		False: either no log type or last log type is "OUT", so his next Ltg Type should be "IN".
	"""
    employee = frappe.get_value('Employee', {'user_id': frappe.session.user})
    logs = []
    today = nowdate()
    if not employee:
        frappe.throw(_('Please link an employee to the logged in user to proceed further.'))
    shift_exists = get_current_shift(employee)
    if not shift_exists:
        return response('Resource Not Found', 404, None, f'No Active Shift Found')
    if shift_exists['type'] == 'Early':
        return response('Resource Not Found', 404, None, f"You are checking in too early, checkin is allowed in {shift_exists['data']} minutes ")
    elif shift_exists['type'] == 'Late':
        return response('Resource Not Found', 404, None, f"You are checking out too late, checkout was allowed {shift_exists['data']} minutes ago ")
    elif shift_exists['type'] == 'On Time':
        shift = shift_exists['data']
    else:
        shift = None
    if shift:
        logs = frappe.db.sql('\n\t\t\tselect log_type from `tabEmployee Checkin` where skip_auto_attendance=0 and employee="{employee}" and shift_assignment="{shift_assignment}"\n\t\t\t'.format(employee=employee, shift_assignment=shift.name), as_dict=1)
    else:
        logs = frappe.db.sql('\n\t\t\tselect log_type from `tabEmployee Checkin` where date(time)=date("{date}") and skip_auto_attendance=0 and employee="{employee}"\n\t\t\t'.format(date=today, employee=employee), as_dict=1)
    val = [log.log_type for log in logs]
    if not val or (val and val[-1] == 'OUT'):
        return False
    else:
        return True

