    if args.repeat == 'Weekly':
        if args.sunday:
            week_days.append('Sunday')
        if args.monday:
            week_days.append('Monday')
        if args.tuesday:
            week_days.append('Tuesday')
        if args.wednesday:
            week_days.append('Wednesday')
        if args.thursday:
            week_days.append('Thursday')
        if args.friday:
            week_days.append('Friday')
        if args.saturday:
            week_days.append('Saturday')
    return week_days

