def prepare_depreciation_data(self):
    if self.calculate_depreciation:
        self.value_after_depreciation = 0
        self.set_depreciation_rate()
        self.make_depreciation_schedule()
        self.set_accumulated_depreciation()
    else:
        self.finance_books = []
        self.value_after_depreciation = flt(self.gross_purchase_amount) - flt(self.opening_accumulated_depreciation)

def set_depreciation_rate(self):
    for d in self.get('finance_books'):
        d.rate_of_depreciation = flt(self.get_depreciation_rate(d, on_validate=True), d.precision('rate_of_depreciation'))

def get_depreciation_rate(self, args, on_validate=False):
    if isinstance(args, string_types):
        args = json.loads(args)

def make_depreciation_schedule(self):
    if 'Manual' not in [d.depreciation_method for d in self.finance_books]:
        self.schedules = []
    if self.get('schedules') or not self.available_for_use_date:
        return
    for d in self.get('finance_books'):
        self.validate_asset_finance_books(d)
        value_after_depreciation = flt(self.gross_purchase_amount) - flt(self.opening_accumulated_depreciation)
        d.value_after_depreciation = value_after_depreciation
        number_of_pending_depreciations = cint(d.total_number_of_depreciations) - cint(self.number_of_depreciations_booked)
        has_pro_rata = self.check_is_pro_rata(d)
        if has_pro_rata:
            number_of_pending_depreciations += 1
        skip_row = False
        for n in range(number_of_pending_depreciations):
            if skip_row:
                continue
            depreciation_amount = self.get_depreciation_amount(value_after_depreciation, d.total_number_of_depreciations, d)
            if not has_pro_rata or n < cint(number_of_pending_depreciations) - 1:
                schedule_date = add_months(d.depreciation_start_date, n * cint(d.frequency_of_depreciation))
                monthly_schedule_date = add_months(schedule_date, -d.frequency_of_depreciation + 1)
            if has_pro_rata and n == 0:
                depreciation_amount, days, months = get_pro_rata_amt(d, depreciation_amount, self.available_for_use_date, d.depreciation_start_date)
                monthly_schedule_date = add_months(d.depreciation_start_date, -months + 1)
            elif has_pro_rata and n == cint(number_of_pending_depreciations) - 1:
                to_date = add_months(self.available_for_use_date, n * cint(d.frequency_of_depreciation))
                depreciation_amount, days, months = get_pro_rata_amt(d, depreciation_amount, schedule_date, to_date)
                monthly_schedule_date = add_months(schedule_date, 1)
                schedule_date = add_days(schedule_date, days)
                last_schedule_date = schedule_date
            if not depreciation_amount:
                continue
            value_after_depreciation -= flt(depreciation_amount, self.precision('gross_purchase_amount'))
            if d.expected_value_after_useful_life and (n == cint(number_of_pending_depreciations) - 1 and value_after_depreciation != d.expected_value_after_useful_life or value_after_depreciation < d.expected_value_after_useful_life):
                depreciation_amount += value_after_depreciation - d.expected_value_after_useful_life
                skip_row = True
            if depreciation_amount > 0:
                if self.allow_monthly_depreciation:
