@frappe.whitelist()
def export_data(doctype=None, parent_doctype=None, all_doctypes=True, with_data=False, select_columns=None, filters=None, link=None, google_sheet_id=None, sheet_name=None, owner=None, client_id=None, name=None):
    _doctype = doctype
    if isinstance(_doctype, list):
        _doctype = _doctype[0]
    make_access_log(doctype=_doctype, columns=select_columns, filters=filters, method=parent_doctype)
    exporter = DataExporter(doctype=doctype, parent_doctype=parent_doctype, all_doctypes=all_doctypes, with_data=with_data, select_columns=select_columns, filters=filters, link=link, google_sheet_id=google_sheet_id, sheet_name=sheet_name, owner=owner, client_id=client_id, name=name)
    result = exporter.build_response()
    return result

@frappe.whitelist()
def update_google_sheet_daily():
    yesterday = add_days(nowdate(), -1)
    list_of_export = frappe.get_list('Google Sheet Data Export', {'enable_auto_update': 1, 'last_execution_date': yesterday}, ['name'], limit=1)
    for e in list_of_export:
        doc = frappe.get_doc('Google Sheet Data Export', e.name)
        frappe.enqueue(export_data, doctype=doc.reference_doctype, select_columns=doc.field_cache, filters=doc.filter_cache, with_data=1, link=doc.link, google_sheet_id=doc.google_sheet_id, sheet_name=doc.sheet_name, owner=doc.owner, client_id=doc.client_id, name=doc.name, is_async=True, queue='long', timeout=9000)

@frappe.whitelist()
def get_client_id():
    SERVICE_ACCOUNT_FILE = os.getcwd() + '/' + cstr(frappe.local.site) + frappe.local.conf.google_sheet
    f = open(SERVICE_ACCOUNT_FILE)
    cred = json.load(f)
    return cred['client_email']

@frappe.whitelist()
def remove_quotes(value):
    if value.startswith('"'):
        value = value[1:]
    if value.endswith('"'):
        value = value[:-1]
    return value

def get_column_identifier(num_columns):

    def number_to_column_letter(n):
        result = ''
        while n > 0:
            n, remainder = divmod(n - 1, 26)
            result = chr(65 + remainder) + result
        return result
    return number_to_column_letter(num_columns)

def prepare_args(self):
    if self.select_columns:
        self.select_columns = parse_json(self.select_columns)
    if self.filters:
        self.filters = parse_json(self.filters)
    self.docs_to_export = {}
    if self.doctype:
        if isinstance(self.doctype, str):
            self.doctype = [self.doctype]
        if len(self.doctype) > 1:
            self.docs_to_export = self.doctype[1]
        self.doctype = self.doctype[0]
    if not self.parent_doctype:
        self.parent_doctype = self.doctype
    self.column_start_end = {}
    if self.all_doctypes:
        self.child_doctypes = []
        for df in frappe.get_meta(self.doctype).get_table_fields():
            self.child_doctypes.append(dict(doctype=df.options, parentfield=df.fieldname))
    if not self.sheet_name:
        self.sheet_name = 'sheet1'

def build_response(self):
    self.writer = UnicodeWriter()
    self.name_field = 'parent' if self.parent_doctype != self.doctype else 'name'
    self.writer.writerow([''])
    self.labelrow = []
    self.fieldrow = []
    self.columns = []
    self.build_field_columns(self.doctype)
    if self.all_doctypes:
        for d in self.child_doctypes:
            if self.select_columns and self.select_columns.get(d['doctype'], None) or not self.select_columns:
                self.build_field_columns(d['doctype'], d['parentfield'])
    self.column = self.labelrow
    values = self.add_data()
    if self.with_data and (not values):
        frappe.msgprint(_('No Data'), _('There is no data to be exported'), indicator_color='orange')
    if not self.link:
        self.create()
    sheet = self.build_connection_with_sheet()
    if not sheet:
        frappe.msgprint(frappe._('We do not have access to this sheet. Kindly, share your sheet with the following:<br><br> <b>{0}</b>').format(str(self.client_id)), indicator='red', title='Warning')
    else:
        if not self.check_if_sheet_exist(sheet):
            self.add_sheet()
        self.update_sheet(values)
        self.batch_update(sheet)
    if self.with_data and (not values):
        frappe.respond_as_web_page(_('No Data'), _('There is no data to be exported'), indicator_color='orange')
    result = {'google_sheet_id': self.google_sheet_id, 'link': self.link, 'sheet_name': self.sheet_name}
    frappe.db.set_value('Google Sheet Data Export', self.name, 'last_execution_date', nowdate())
    return result

def build_field_columns(self, dt, parentfield=None):
    meta = frappe.get_meta(dt)
    tablecolumns = []
    table_name = 'tab' + dt
    fields = [sub['name'] for sub in frappe.db.get_table_columns_description(table_name)]
    for f in self.select_columns[dt]:
        field = meta.get_field(f)
        if field:
            tablecolumns.append(field)
    _column_start_end = frappe._dict(start=0)
    if dt == self.doctype:
        if meta.get('autoname') and meta.get('autoname').lower() == 'prompt' or self.with_data:
            self._append_name_column()
        if meta.get('istable') and (not self.with_data):
            self.append_field_column(frappe._dict({'fieldname': 'parent', 'parent': '', 'label': 'Parent', 'fieldtype': 'Data', 'reqd': 1, 'info': _('Parent is the name of the document to which the data will get added to.')}))
        _column_start_end = frappe._dict(start=0)
    else:
        _column_start_end = frappe._dict(start=len(self.columns))
        if self.with_data:
            self._append_name_column(dt)
    for docfield in tablecolumns:
        self.append_field_column(docfield)
    _column_start_end.end = len(self.columns) + 1
    self.column_start_end[dt, parentfield] = _column_start_end

def append_field_column(self, docfield):
    if not docfield:
        return
    if docfield.fieldname in ('parenttype', 'trash_reason'):
        return
    if docfield.hidden:
        return
    if self.select_columns and docfield.fieldname not in self.select_columns.get(docfield.parent, []) and (docfield.fieldname != 'name'):
        return
    if docfield.parent and docfield.parent != self.doctype:
        self.labelrow.append(f'{_(docfield.label)}({_(docfield.parent)})')
    else:
        self.labelrow.append(_(docfield.label))
    self.fieldrow.append(docfield.fieldname)
    self.columns.append(docfield.fieldname)

def add_data(self):
    from frappe.query_builder import DocType
    data = []
    data.append(self.labelrow)
    order_by = None
    table_columns = frappe.db.get_table_columns(self.parent_doctype)
    if 'lft' in table_columns and 'rgt' in table_columns:
        order_by = f'`tab{self.parent_doctype}`.`lft` asc'
    self.data = frappe.get_list(self.doctype, fields=['*'], filters=self.filters, limit_page_length=None, order_by=order_by)
    cell_colour = []
    row_index = 0
    for doc in self.data:
        rows = []
        self.add_data_row(rows, self.doctype, None, doc, 0, cell_colour, row_index)
        if self.all_doctypes:
            for c in self.child_doctypes:
                if self.select_columns.get(c.get('doctype')):
                    child_doctype_table = DocType(c['doctype'])
                    data_row = frappe.qb.from_(child_doctype_table).select('*').where(child_doctype_table.parent == doc.name).where(child_doctype_table.parentfield == c['parentfield']).where(child_doctype_table.parenttype == self.doctype).orderby(child_doctype_table.idx)
                    for ci, child in enumerate(data_row.run(as_dict=True)):
                        if ci > 0:
                            self.add_data_row(rows, self.doctype, None, doc, ci, cell_colour, row_index)
                        self.add_data_row(rows, c['doctype'], c['parentfield'], child, ci, cell_colour, row_index)
        for row in rows:
            data.append(row)
        row_index += 1
    self.cell_colour = cell_colour
    return data

def add_data_row(self, rows, dt, parentfield, doc, rowidx, cell_colour, row_index):
    d = doc.copy()
    meta = frappe.get_meta(dt)
    if self.all_doctypes:
        d.name = f'"{d.name}"'
    _column_start_end = self.column_start_end.get((dt, parentfield))
    if _column_start_end:
        if len(rows) < rowidx + 1:
            rows.append([''] * (len(self.columns) + 1))
        row = rows[rowidx]
        for i, c in enumerate(self.columns[_column_start_end.start:_column_start_end.end]):
            df = meta.get_field(c)
            value = str(d.get(c, ''))
            value = remove_quotes(value)
            if len(value) >= 50000:
                cell_colour.append({'column': _column_start_end.start + i, 'row': row_index + 1})
                row[_column_start_end.start + i] = f'ERROR - Description Length is more than 50,000 so can not import Data'
            else:
                row[_column_start_end.start + i] = value

def build_connection_with_sheet(self):
    api = self.initialize_service()
    service = api['service']
