@property
def non_compliant_employees(self):
    if self._non_compliant_employees is None:
        reported_employees = frappe.db.get_list('Employee Daily Action', filters={'date': self.yesterday, 'docstatus': 1}, pluck='employee')
        self._non_compliant_employees = frappe.db.get_list('Employee', filters={'status': 'Active', 'is_in_ows': 'Yes', 'name': ['NOT IN', reported_employees]}, fields=['name', 'attendance_by_timesheet', 'shift_working', 'holiday_list', 'employee_name'])
    return self._non_compliant_employees

@property
def shift_working_employee_schedule(self):
    if self._shift_working_schedules is None:
        shift_employees = [emp.name for emp in self.non_compliant_employees if emp.shift_working]
        if not shift_employees:
            self._shift_working_schedules = set()
        else:
            self._shift_working_schedules = set(frappe.db.get_all('Employee Schedule', filters={'date': self.yesterday, 'employee': ['IN', shift_employees], 'employee_availability': 'Working'}, pluck='employee'))
    return self._shift_working_schedules

@property
def leave_attendance(self):
    if self._leave_attendance is None:
        non_shift_employees = [emp.name for emp in self.non_compliant_employees if not emp.shift_working]
        if not non_shift_employees:
            self._leave_attendance = set()
        else:
            self._leave_attendance = set(frappe.db.get_all('Attendance', filters={'attendance_date': self.yesterday, 'status': 'On Leave', 'employee': ['IN', non_shift_employees]}, pluck='employee'))
    return self._leave_attendance

@property
def yesterday_holiday_status(self):
    if self._holiday_lists is None:
        holiday_lists = {emp.holiday_list for emp in self.non_compliant_employees if not emp.shift_working and emp.holiday_list}
        if not holiday_lists:
            self._holiday_lists = set()
        else:
            result = frappe.db.sql("\n\t\t\t\t\tSELECT DISTINCT hl.name\n\t\t\t\t\tFROM `tabHoliday List` hl\n\t\t\t\t\tINNER JOIN `tabHoliday` h ON h.parent = hl.name AND h.parenttype = 'Holiday List'\n\t\t\t\t\tWHERE h.holiday_date = %s \n\t\t\t\t\tAND hl.name IN ({})\n\t\t\t\t".format(','.join(['%s'] * len(holiday_lists))), [self.yesterday] + list(holiday_lists), as_dict=False)
            self._holiday_lists = {row[0] for row in result}
    return self._holiday_lists

def send_notification_mail(self, recipient, employee_name):
    try:
        msg = frappe.render_template('one_fm/templates/emails/employee_daily_action_check.html', context={'employee_name': employee_name, 'yesterday': self.yesterday})
        sender = frappe.get_value('Email Account', filters={'default_outgoing': 1}, fieldname='email_id') or None
        sendemail(sender=sender, recipients=[recipient], content=msg, subject='Employee Daily Action Check', delayed=False, is_scheduler_email=True)
    except Exception as e:
        frappe.log_error(f'Failed to send notification to {recipient}: {str(e)}', 'Employee Daily Action Check Notification')

def notify_employee(self):
    if not self.non_compliant_employees:
        return
    employee_schedules = self.shift_working_employee_schedule
    leave_attendance = self.leave_attendance
    holiday_status = self.yesterday_holiday_status
    for employee in self.non_compliant_employees:
        recipient = None
        should_notify = False
        if employee.shift_working and employee.name in employee_schedules or (not employee.shift_working and employee.holiday_list not in holiday_status and (employee.name not in leave_attendance)):
            recipient = get_approver_user(employee.name)
            should_notify = True
        if should_notify and recipient:
            self.send_notification_mail(recipient=recipient, employee_name=employee.employee_name)

